import com.github.easylog.annotation.EasyLog;
import com.imile.common.page.PaginationResult;
import com.imile.common.result.Result;
import com.imile.purchase.converter.ConverterService;
import com.imile.purchase.dto.po.PurchaseOrderDTO;
import com.imile.purchase.enums.PurchaseDocumentEnum;
import com.imile.purchase.order.bo.OrderItemBO;
import com.imile.purchase.order.dto.OrderItemDTO;
import com.imile.purchase.query.PurchaseOrderPageQuery;
import com.imile.purchase.query.PurchaseOrderVoucherExportQuery;
import com.imile.purchase.service.order.PurchaseOrderManagerService;
import com.imile.purchase.service.permission.PermissionService;
import com.imile.purchase.vo.DeleteFailVO;
import com.imile.purchase.vo.manager.AssociatedPaymentRequestVO;
import com.imile.purchase.vo.manager.AssociatedPurchaseReceiptVO;
import com.imile.purchase.vo.manager.po.PurchaseOrderItemDetailExportVO;
import com.imile.purchase.vo.manager.po.PurchaseOrderPageVO;
import com.imile.purchase.vo.manager.po.PurchaseOrderVO;
import com.imile.purchase.vo.manager.po.PurchaseOrderVoucherExportVO;
import com.imile.purchase.web.BaseController;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import javax.annotation.Resource;
import javax.servlet.http.HttpServletRequest;
import javax.validation.constraints.NotBlank;
import javax.validation.constraints.NotNull;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;


/**
 * @author Vita
 * @menu 采购订单管理（PO）
 * @date 2022/12/16
 */
@RestController
@RequestMapping("/manager/po")
@Validated
@Slf4j
public class PurchaseOrderManagerController extends BaseController {

    @Autowired
    private PurchaseOrderManagerService purchaseOrderManagerService;
    @Autowired
    private ConverterService converterService;

    @Resource
    private PermissionService permissionService;

    /**
     * 关联合同，补全PO信息
     *
     * @param prCode
     * @param contractCode
     * @param poCode
     * @return
     */
    @PostMapping("/associateContract")
    @EasyLog
    public Result<String> associateContract(@NotBlank String prCode, @NotBlank String contractCode, @NotBlank String poCode) {
        String contract = purchaseOrderManagerService.associateContract(prCode, contractCode, poCode);
        return Result.ok(contract);
    }

    /**
     * PR下推生成PO
     *
     * @param prCode       PR编号
     * @param contractCode 合同编号
     * @return
     */
    @PostMapping("/create")
    @EasyLog
    public Result<Void> createPo(@NotBlank String prCode, @NotBlank String contractCode) {
        purchaseOrderManagerService.createPo(prCode, contractCode);
        return Result.ok();
    }

    /**
     * 保存PO
     *
     * @param purchaseOrderDTO
     * @return
     */
    @PostMapping("/save")
    @EasyLog
    public Result<Void> savePo(@Validated @RequestBody PurchaseOrderDTO purchaseOrderDTO) {
        converterService.withAnnotationForSingle(purchaseOrderDTO);
        converterService.withAnnotation(purchaseOrderDTO.getPoDetailList());
        purchaseOrderManagerService.savePo(purchaseOrderDTO);
        return Result.ok();
    }

    /**
     * 提交PO
     *
     * @param purchaseOrderDTO
     * @return
     */
    @PostMapping("/submit")
    @EasyLog
    public Result<Void> submitPo(@Validated @RequestBody PurchaseOrderDTO purchaseOrderDTO) {
        log.info("submit PO: " + JSON.toJSONString(purchaseOrderDTO));
        converterService.withAnnotationForSingle(purchaseOrderDTO);
        converterService.withAnnotation(purchaseOrderDTO.getPoDetailList());
        purchaseOrderManagerService.savePo(purchaseOrderDTO);
        purchaseOrderManagerService.submitPo(purchaseOrderDTO);
        return Result.ok();
    }

    /**
     * 撤销提交
     *
     * @param poCode
     * @return
     */
    @PostMapping("/recall")
    @EasyLog
    public Result<Void> recall(@NotBlank String poCode) {
        log.info("PO recall: " + poCode);
        purchaseOrderManagerService.recall(poCode);
        return Result.ok();
    }

    /**
     * PO列表（分页+条件）V2
     *
     * @param poPageQuery
     * @return
     */
    @PostMapping("/page")
    public Result<PaginationResult<PurchaseOrderPageVO>> pagePo(@RequestBody PurchaseOrderPageQuery poPageQuery) {
        checkParam(poPageQuery);
        converterService.withAnnotationForSingle(poPageQuery);
        PaginationResult<PurchaseOrderPageVO> poPageList = purchaseOrderManagerService.page(poPageQuery);
        List<PurchaseOrderPageVO> results = poPageList.getResults();
        if (results != null) {
            converterService.withAnnotation(results);
            results.forEach(poPageVO -> {
                List<AssociatedPurchaseReceiptVO> associatedRiList = poPageVO.getAssociatedRiList();
                if (associatedRiList != null) {
                    converterService.withAnnotation(associatedRiList);
                }
            });
        }
        return Result.ok(poPageList);
    }

    /**
     * PO 的单据导出
     *
     * @param request            Request 请求
     * @param voucherExportQuery 查询参数
     * @return Result<PaginationResult < PurchaseOrderVoucherExportVO>>
     */
    @PostMapping("/voucher/export")
    public Result<PaginationResult<PurchaseOrderVoucherExportVO>> getPOVoucherExportPage(HttpServletRequest request, PurchaseOrderVoucherExportQuery voucherExportQuery) {
        setExcelCallBackParam(request, voucherExportQuery);
        converterService.withAnnotationForSingle(voucherExportQuery);
        PaginationResult<PurchaseOrderVoucherExportVO> poPageList = purchaseOrderManagerService.getPOVoucherExportPage(voucherExportQuery);
        return Result.ok(poPageList);
    }


    /**
     * PO 的单据明细导出
     *
     * @param request            Request 请求
     * @param voucherExportQuery 查询参数
     * @return Result<PaginationResult < PurchaseOrderVoucherExportVO>>
     */
    @PostMapping("/item/detail/export")
    public Result<PaginationResult<PurchaseOrderItemDetailExportVO>> getPOItemDetailExport(HttpServletRequest request, PurchaseOrderVoucherExportQuery voucherExportQuery) {
        setExcelCallBackParam(request, voucherExportQuery);
        converterService.withAnnotationForSingle(voucherExportQuery);
        PaginationResult<PurchaseOrderItemDetailExportVO> poItemDetailList = purchaseOrderManagerService.getPOItemDetailExport(voucherExportQuery);
        return Result.ok(poItemDetailList);
    }


    /**
     * 单个PO详情V2
     *
     * @param poCode
     * @return
     */
    @GetMapping("/getOne")
    @EasyLog
    public Result<PurchaseOrderVO> getOneByPoCode(@NotBlank String poCode) {
        permissionService.checkPermissionOrException(PurchaseDocumentEnum.PO, Collections.singletonList(poCode));
        PurchaseOrderVO purchaseOrderVO = purchaseOrderManagerService.getOneByPoCode(poCode);
        converterService.withAnnotationForSingle(purchaseOrderVO);
        converterService.withAnnotation(purchaseOrderVO.getPoDetailList());
        converterService.withAnnotation(purchaseOrderVO.getPoBudgetAllocationList());
        return Result.ok(purchaseOrderVO);
    }

    /**
     * 批量删除PO
     *
     * @param poCodeList
     * @return
     */
    @PostMapping("/delete")
    @EasyLog
    public Result<HashMap<String, Object>> deletePo(@RequestBody @NotNull List<String> poCodeList) {
        List<DeleteFailVO> deleteFailVOS = purchaseOrderManagerService.deletePo(poCodeList);
        if (deleteFailVOS == null) {
            return Result.ok();
        } else {
            HashMap<String, Object> map = new HashMap<>();
            map.put("status", "failure");
            map.put("message", deleteFailVOS);
            return Result.ok(map);
        }
    }

    /**
     * 手动完结PO
     *
     * @param poCode
     * @return
     */
    @PostMapping("/complete")
    @EasyLog
    public Result<Void> completePo(@NotBlank String poCode) {
        log.info("complete PO by hand: " + poCode);
        purchaseOrderManagerService.completePo(poCode);
        return Result.ok();
    }

    /**
     * 查看关联验收单号
     *
     * @param poCode
     * @return
     */
    @GetMapping("/associatedRi")
    @EasyLog
    public Result<List<AssociatedPurchaseReceiptVO>> getAssociatedRi(@NotBlank String poCode, String riCode) {
        List<AssociatedPurchaseReceiptVO> list = purchaseOrderManagerService.getAssociatedRi(poCode, riCode);
        converterService.withAnnotation(list);
        return Result.ok(list);
    }

    /**
     * 查看关联付款申请单号
     *
     * @param poCode
     * @return
     */
    @GetMapping("/associatedPy")
    @EasyLog
    public Result<List<AssociatedPaymentRequestVO>> getAssociatedPy(@NotBlank String poCode) {
        List<AssociatedPaymentRequestVO> list = purchaseOrderManagerService.getAssociatedPy(poCode);
        converterService.withAnnotation(list);
        return Result.ok(list);
    }

    /**
     * PO复制
     *
     * @param oldPoCode
     * @return 新PO号
     */
    @GetMapping("/copyPo")
    @EasyLog
    public Result<String> copyPo(@NotBlank String oldPoCode) {
        return Result.ok(purchaseOrderManagerService.copyPo(oldPoCode));
    }

    /**
     * 补偿接口：PO审核通过后发送邮件给供应商商务联系人
     *
     * @param poCode
     * @return
     */
    @GetMapping("/poSendEmail")
    @EasyLog
    public Result<Void> poSendEmail(@NotBlank String poCode) {
        purchaseOrderManagerService.poSendEmail(poCode);
        return Result.ok();
    }

    /**
     * 修改审核中的单据
     *
     * @param purchaseOrderDTO 目前只能改费用分摊
     * @return
     */
    @PostMapping("/updateApproval")
    @EasyLog
    public Result<Void> updateApproval(@RequestBody PurchaseOrderDTO purchaseOrderDTO) {
        log.info("PO saveOrUpdate approval: " + JSON.toJSONString(purchaseOrderDTO));
        purchaseOrderManagerService.updateApproval(purchaseOrderDTO);
        return Result.ok();
    }


    /**
     * po单反审批
     *
     * @param poCode po单
     */
    @GetMapping("/anti/approval")
    @EasyLog
    public Result<Void> antiApproval(@NotBlank String poCode) {
        log.info("antiApproval ｜ poCode={}", poCode);
        purchaseOrderManagerService.antiApproval(poCode);
        return Result.ok();
    }


    /**
     * 根据金额计算数量、根据数量计算金额
     *
     */
    @PostMapping("/calculateAmount")
    public Result<OrderItemBO> calculateAmount(@RequestBody OrderItemDTO dto) {
        return Result.ok(purchaseOrderManagerService.calculateAmount(dto));
    }


    /**
     * 修改订单输入模式
     *
     * @param poCode po单
     */
    @GetMapping("/change/itemInputMode")
    public Result<Void> changeItemInputMode(@NotBlank String poCode, @NotBlank String itemInputMode) {
        purchaseOrderManagerService.changeItemInputMode(poCode, itemInputMode);
        return Result.ok();
    }

}

