    /**
     * PR下推生成PO
     *
     * @param prCode       PR编号
     * @param contractCode 合同编号
     * @return
     */
    @Override
    @Transactional
    public void createPo(String prCode, String contractCode) {
        //判断PR是否存在、是否审核通过、是否完结
        PurchaseRequisitionDO purchaseRequisitionDO = purchaseRequisitionDAO.getByPrCode(prCode);
        if (purchaseRequisitionDO == null) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_REQUISITION_NOT_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_REQUISITION_NOT_EXIST.getDesc()));
        }
        if (!SupplierDataStatusEnums.PASS.getCode().equals(purchaseRequisitionDO.getAuditStatus())) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_REQUISITION_IS_NOT_PASS.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_REQUISITION_IS_NOT_PASS.getDesc()));
        }
        if (CompleteStatusEnums.COMPLETED.getCode().equals(purchaseRequisitionDO.getCompleteStatus())) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_REQUISITION_COMPLETED.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_REQUISITION_COMPLETED.getDesc()));
        }
        //判断合同是否存在、归档通过
        PurchaseContractInfoDO purchaseContractInfoDO = purchaseContractInfoDAO.getByContractCode(contractCode);

        if (purchaseContractInfoDO == null) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_CONTRACT_NOT_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_CONTRACT_NOT_EXIST.getDesc()));
        }
        if (!StatusEnums.ACTIVE.getCode().equals(purchaseContractInfoDO.getStatus()) || !SupplierDataStatusEnums.PASS.getCode().equals(purchaseContractInfoDO.getFilingAuditStatus())) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_CONTRACT_NOT_FILED.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_CONTRACT_NOT_FILED.getDesc()));
        }

        //判断PR和合同的采购编码是否有交集
        List<PurchaseRequisitionDetailDO> prDetailDOS = prDetailDAO.getPrDetailByPrCode(prCode);
        List<String> itemCodesOfPr = prDetailDOS.stream().map(PurchaseRequisitionDetailDO::getPurchaseItemCode).collect(Collectors.toList());
        List<PurchaseContractDetailDO> contractDetailDOS = purchaseContractDetailDAO.getDetailByContractCode(contractCode);
        List<PurchaseContractDetailPriceSettingDO> purchaseContractDetailPriceSettingDOList = purchaseContractDetailPriceSettingDAO.getByContractCode(contractCode);

        List<String> itemCodeResult = contractDetailDOS.stream().map(PurchaseContractDetailDO::getPurchaseItemCode).filter(itemCodesOfPr::contains)
                .distinct()
                .collect(Collectors.toList());
        if (CollectionUtils.isEmpty(itemCodeResult)) {
            throw BusinessException.get(ErrorCodeEnums.NO_IDENTICAL_PURCHASE_ITEM_CODE_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.NO_IDENTICAL_PURCHASE_ITEM_CODE_EXIST.getDesc()));
        }


        //生成POCode
        String poCode = serialService.createPurchaseOrderCode();
        //新增 PO表
        PurchaseOrderDO purchaseOrderDO = new PurchaseOrderDO();
        purchaseOrderDO.setPoCode(poCode);
        purchaseOrderDO.setPrCode(prCode);
        purchaseOrderDO.setContractCode(contractCode);
        purchaseOrderDO.setAuditStatus(SupplierDataStatusEnums.SAVE.getCode());
        purchaseOrderDO.setPurchaseDate(LocalDateTime.now());
        purchaseOrderDO.setBuyerCode(purchaseRequisitionDO.getBuyerCode());
        purchaseOrderDO.setDeliveryAddress(purchaseRequisitionDO.getDeliveryPoint());
        purchaseOrderDO.setOneDeptId(purchaseRequisitionDO.getOneDeptId());
        purchaseOrderDO.setTwoDeptId(purchaseRequisitionDO.getTwoDeptId());
        purchaseOrderDO.setShippingAddress(purchaseContractInfoDO.getShipFromAddress());
        purchaseOrderDO.setSiteNumber(purchaseContractInfoDO.getSiteNumber());
        //新增 PO的detail表
        ArrayList<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOList = new ArrayList<>();
        Map<String, PurchaseContractDetailDO> contractDetailDOMap = contractDetailDOS.stream().collect(Collectors.toMap(PurchaseContractDetailDO::getPurchaseItemCode, Function.identity(), (k, v) -> k));
        Map<String, List<PurchaseContractDetailPriceSettingDO>> purchaseContractDetailPriceSettingDOMap = purchaseContractDetailPriceSettingDOList.stream()
                .collect(Collectors.groupingBy(PurchaseContractDetailPriceSettingDO::getItemCode));

        for (String itemCode : itemCodeResult) {
            PurchaseOrderDetailDO purchaseOrderDetailDO = new PurchaseOrderDetailDO();
            purchaseOrderDetailDO.setPoCode(poCode);
            purchaseOrderDetailDO.setPurchaseItemCode(itemCode);
            PurchaseContractDetailDO purchaseContractDetailDO = contractDetailDOMap.get(itemCode);
            purchaseOrderDetailDO.setItemCodeTaxRate(purchaseContractDetailDO.getItemCodeTaxRate());
            purchaseOrderDetailDO.setPurchaseRemarks(purchaseContractDetailDO.getPurchaseRemarks());
            purchaseOrderDetailDO.setPriceMatchMode(purchaseContractDetailDO.getPriceMatchMode());
            purchaseOrderDetailDO.setChargingMethod(purchaseContractDetailDO.getChargingMethod());

            List<OrderDetailPriceSettingDO> subOrderDetailPriceSettingDOList =new ArrayList<>();
            List<PurchaseContractDetailPriceSettingDO> subPurchaseContractDetailPriceSettingDOList = purchaseContractDetailPriceSettingDOMap.get(itemCode);
            if (CollectionUtils.isNotEmpty(subPurchaseContractDetailPriceSettingDOList)) {
                 subOrderDetailPriceSettingDOList = subPurchaseContractDetailPriceSettingDOList.stream()
                        .map(o -> {
                            OrderDetailPriceSettingDO orderDetailPriceSettingDO = new OrderDetailPriceSettingDO();
                            orderDetailPriceSettingDO.setPoCode(poCode);
                            orderDetailPriceSettingDO.setItemCode(o.getItemCode());
                            orderDetailPriceSettingDO.setPrice(o.getPrice());
                            orderDetailPriceSettingDO.setMinQty(o.getMinQty());
                            orderDetailPriceSettingDO.setMaxQty(o.getMaxQty());
                            return orderDetailPriceSettingDO;
                        }).collect(Collectors.toList());
            }
            OrderBO.PurchaseOrderDetailBO purchaseOrderDetailBO = new OrderBO.PurchaseOrderDetailBO();
            purchaseOrderDetailBO.setPurchaseOrderDetailDO(purchaseOrderDetailDO);
            purchaseOrderDetailBO.setOrderDetailPriceSettingDOList(subOrderDetailPriceSettingDOList);
            purchaseOrderDetailBOList.add(purchaseOrderDetailBO);
        }
        //新增PO费用分摊（默认取PR）
        List<PurchaseRequisitionBudgetAllocationDO> purchaseRequisitionBudgetAllocationDOS = purchaseRequisitionBudgetAllocationDAO.getByPrCode(purchaseRequisitionDO.getPrCode());
        List<PurchaseOrderBudgetAllocationDO> purchaseOrderBudgetAllocationDOS = purchaseRequisitionBudgetAllocationDOS.stream()
                .map(item -> {
                    PurchaseOrderBudgetAllocationDO purchaseOrderBudgetAllocationDO = new PurchaseOrderBudgetAllocationDO();
                    BeanUtils.copyProperties(item, purchaseOrderBudgetAllocationDO);
                    purchaseOrderBudgetAllocationDO.setId(IdWorkerUtil.getId());
                    purchaseOrderBudgetAllocationDO.setPoCode(poCode);
                    purchaseOrderBudgetAllocationDO.setFeeBearingAmount(item.getFeeBearingAmount());
                    return purchaseOrderBudgetAllocationDO;
                }).collect(Collectors.toList());


        OrderBO orderBO = OrderBO.builder()
                .purchaseOrderDO(purchaseOrderDO)
                .purchaseOrderDetailBOList(purchaseOrderDetailBOList)
                .purchaseOrderBudgetAllocationDOList(purchaseOrderBudgetAllocationDOS)
                .build();
        purchaseOrderManager.saveOrUpdate(orderBO);
    }


