    /**
     * 保存PO
     *
     * @param purchaseOrderDTO
     * @return
     */
    @Override
    @Transactional
    public void savePo(PurchaseOrderDTO purchaseOrderDTO) {
        String poCode = purchaseOrderDTO.getPoCode();
        OrderBO orderBO = purchaseOrderManager.getOrderBO(poCode);
        PurchaseAssert.isEmpty(orderBO, ErrorCodeEnums.NOT_EXIST, poCode);
        PurchaseOrderDO purchaseOrderDO = orderBO.getPurchaseOrderDO();
        if (purchaseOrderDO == null) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getDesc()));
        }
        //判断PO是否可修改
        Integer auditStatus = purchaseOrderDO.getAuditStatus();
        if (SupplierDataStatusEnums.SUBMIT.getCode().equals(auditStatus) || SupplierDataStatusEnums.PASS.getCode().equals(auditStatus)) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_ORDER_CANNOT_EDIT.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_ORDER_CANNOT_EDIT.getDesc()));
        }
        if (Strings.isNotBlank(purchaseOrderDO.getContractCode())) {
            PurchaseContractInfoDO purchaseContractInfoDO = purchaseContractInfoDAO.getByContractCode(purchaseOrderDO.getContractCode());
            if (Objects.nonNull(purchaseContractInfoDO)) {
                purchaseOrderDO.setSiteNumber(purchaseContractInfoDO.getSiteNumber());
            }
        }
        //修改 PO表
        BeanUtils.copyProperties(purchaseOrderDTO, purchaseOrderDO);
        //新增 PO的Detail表
        List<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOList = new ArrayList<>();
        List<PurchaseOrderDetailDTO> poDetailList = purchaseOrderDTO.getPoDetailList();
        if (CollectionUtils.isNotEmpty(poDetailList)) {
            Map<String, List<PurchaseContractDetailPriceSettingDO>> itemCodeAndPriceMap = purchaseContractInfoManager.getItemDetailMap(purchaseOrderDO.getContractCode());
            List<PurchaseContractDetailDO> contractDetailDOList = purchaseContractDetailDAO.getDetailByContractCode(purchaseOrderDO.getContractCode());
            Map<String, PurchaseContractDetailDO> contractDetailDOMap = contractDetailDOList.stream().collect(Collectors.toMap(PurchaseContractDetailDO::getPurchaseItemCode, Function.identity(), (v1, v2) -> v1));
            //数据新增
            for (PurchaseOrderDetailDTO purchaseOrderDetailDTO : poDetailList) {
                PurchaseOrderDetailDO purchaseOrderDetailDO = new PurchaseOrderDetailDO();
                BeanUtils.copyProperties(purchaseOrderDetailDTO, purchaseOrderDetailDO);
                purchaseOrderDetailDO.setPoCode(poCode);
                PurchaseContractDetailDO purchaseContractDetailDO = contractDetailDOMap.get(purchaseOrderDetailDTO.getPurchaseItemCode());
                purchaseOrderDetailDO.setItemCodeTaxRate(purchaseContractDetailDO.getItemCodeTaxRate());
                purchaseOrderDetailDO.setPriceMatchMode(purchaseContractDetailDO.getPriceMatchMode());
                purchaseOrderDetailDO.setChargingMethod(purchaseContractDetailDO.getChargingMethod());
                List<PurchaseContractDetailPriceSettingDO> subPurchaseContractDetailPriceSettingDOList = itemCodeAndPriceMap.get(purchaseOrderDetailDO.getPurchaseItemCode());
                List<OrderDetailPriceSettingDO> subOrderDetailPriceSettingDOList =new ArrayList<>();
                if (CollectionUtils.isNotEmpty(subPurchaseContractDetailPriceSettingDOList)) {
                     subOrderDetailPriceSettingDOList = subPurchaseContractDetailPriceSettingDOList.stream()
                            .map(o -> {
                                OrderDetailPriceSettingDO orderDetailPriceSettingDO = new OrderDetailPriceSettingDO();
                                orderDetailPriceSettingDO.setPoCode(poCode);
                                orderDetailPriceSettingDO.setItemCode(o.getItemCode());
                                orderDetailPriceSettingDO.setPrice(o.getPrice());
                                orderDetailPriceSettingDO.setMinQty(o.getMinQty());
                                orderDetailPriceSettingDO.setMaxQty(o.getMaxQty());
                                return orderDetailPriceSettingDO;
                            }).collect(Collectors.toList());
                }
                OrderBO.PurchaseOrderDetailBO purchaseOrderDetailBO = new OrderBO.PurchaseOrderDetailBO();
                purchaseOrderDetailBO.setPurchaseOrderDetailDO(purchaseOrderDetailDO);
                purchaseOrderDetailBO.setOrderDetailPriceSettingDOList(subOrderDetailPriceSettingDOList);
                purchaseOrderDetailBOList.add(purchaseOrderDetailBO);
            }
        }
        //新增PO费用分摊
        List<PurchaseOrderBudgetAllocationDO> purchaseOrderBudgetAllocationDOS = new ArrayList<>();
        List<PurchaseOrderBudgetAllocationDTO> poBudgetAllocationList = purchaseOrderDTO.getPoBudgetAllocationList();
        if (CollectionUtils.isNotEmpty(poBudgetAllocationList)) {
            for (PurchaseOrderBudgetAllocationDTO item : poBudgetAllocationList) {
                PurchaseOrderBudgetAllocationDO purchaseOrderBudgetAllocationDO = new PurchaseOrderBudgetAllocationDO();
                BeanUtils.copyProperties(item, purchaseOrderBudgetAllocationDO);
                purchaseOrderBudgetAllocationDO.setPoCode(purchaseOrderDO.getPoCode());
                purchaseOrderBudgetAllocationDOS.add(purchaseOrderBudgetAllocationDO);
            }
        }

        OrderBO build = OrderBO.builder()
                .purchaseOrderDO(purchaseOrderDO)
                .purchaseOrderDetailBOList(purchaseOrderDetailBOList)
                .purchaseOrderBudgetAllocationDOList(purchaseOrderBudgetAllocationDOS)
                .build();
        purchaseOrderManager.saveOrUpdate(build);


        //逻辑删除 文件表
        pmsFileInfoDAO.deleteFileHistory(poCode, FileInfoTypeEnums.PO_FILE.getType());
        //新增 文件表
        List<PmsFileInfoDTO> poFileList = purchaseOrderDTO.getPoFileList();
        if (CollectionUtils.isNotEmpty(poFileList)) {
            ArrayList<PmsFileInfoDO> pmsFileInfoDOS = new ArrayList<>();
            for (PmsFileInfoDTO poFileInfoDTO : poFileList) {
                PmsFileInfoDO pmsFileInfoDO = new PmsFileInfoDO();
                BeanUtils.copyProperties(poFileInfoDTO, pmsFileInfoDO);
                pmsFileInfoDO.setFileType(poFileInfoDTO.getFileType());
                pmsFileInfoDOS.add(pmsFileInfoDO);
            }
            pmsFileInfoDAO.insertFileInfos(poCode, FileInfoTypeEnums.PO_FILE.getType(), pmsFileInfoDOS);
        }
    }

    /**
     * 提交PO
     *
     * @param purchaseOrderDTO
     * @return
     */
    @Override
    @Transactional
    public void submitPo(PurchaseOrderDTO purchaseOrderDTO) {
        //必填项检验
        String message = ValidationUtil.validate(purchaseOrderDTO, Submit.class);
        if (StringUtils.isNotBlank(message)) {
            throw BusinessException.get(MsgCodeConstant.PARAM_INVALID, message);
        }
        //filePath不为null
        checkFilePath(purchaseOrderDTO);

        OrderBO orderBO = purchaseOrderManager.getOrderBO(purchaseOrderDTO.getPoCode());
        PurchaseOrderDO purchaseOrderDO = orderBO.getPurchaseOrderDO();
        if (purchaseOrderDO == null) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getDesc()));
        }

        orderBO.checkSubmit();
        //判断PO的预付款到期时间
        Boolean isDownPaymentAndOneHundred = isDownPaymentAndOneHundred(purchaseOrderDO.getContractCode());
        if (isDownPaymentAndOneHundred) {
            LocalDateTime downPaymentWriteOffDate = purchaseOrderDTO.getDownPaymentWriteOffDate();
            if (downPaymentWriteOffDate == null) {
                throw BusinessException.get(ErrorCodeEnums.DOWNPAYMENT_WRITE_OFF_DATE_NOT_NULL.getCode(),
                        I18nUtils.getMessage(ErrorCodeEnums.DOWNPAYMENT_WRITE_OFF_DATE_NOT_NULL.getDesc()));
            }
            if (downPaymentWriteOffDate.toLocalDate().isBefore(LocalDate.now().plusDays(1))) {
                throw BusinessException.get(ErrorCodeEnums.DOWNPAYMENT_WRITE_OFF_DATE_BEFORE_NOW.getCode(),
                        I18nUtils.getMessage(ErrorCodeEnums.DOWNPAYMENT_WRITE_OFF_DATE_BEFORE_NOW.getDesc()));
            }
        }

        this.checkPrAmount(purchaseOrderDO);
        this.checkContractAmount(purchaseOrderDO);
        //OA审批、新增审核记录、修改PO审核状态
        PurchaseContractInfoDO contract = purchaseContractInfoDAO.getByContractCode(purchaseOrderDO.getContractCode());
        String auditCode = null;
        boolean needApproval = Objects.equals(purchaseOrderDTO.getApprovalFlag(), IsDeleteEnum.YES.getValue()) || needApprovalOrgIdList.contains(contract.getContractOrgId());
        if (needApproval) {
            PurchaseRequisitionDO purchaseRequisitionDO = purchaseRequisitionDAO.getByPrCode(purchaseOrderDO.getPrCode());
            ApprovalInfoCreateResultDTO approval = buildAndPushApproval(orderBO,
                    purchaseOrderDTO, purchaseRequisitionDO);
            auditCode = approval.getApprovalId().toString();
        }

        //新增 PO审核记录
        PurchaseOrderAuditDO purchaseOrderAuditDO = new PurchaseOrderAuditDO();
        purchaseOrderAuditDO.setId(IdWorkerUtil.getId());
        purchaseOrderAuditDO.setPoCode(purchaseOrderDTO.getPoCode());
        purchaseOrderAuditDO.setPoInfo(JSON.toJSONString(purchaseOrderDTO));
        //PO审核表
        purchaseOrderAuditDO.setAuditCode(auditCode);
        purchaseOrderAuditDO.setAuditStatus(SupplierDataStatusEnums.SUBMIT.getCode());
        BaseDOUtil.insertDO(purchaseOrderAuditDO);
        purchaseOrderAuditDAO.save(purchaseOrderAuditDO);
        //PO表的审核状态
        purchaseOrderDO.setAuditStatus(SupplierDataStatusEnums.SUBMIT.getCode());
        BaseDOUtil.updateDO(purchaseOrderDO);
        purchaseOrderDAO.updateById(purchaseOrderDO);
        if (!needApproval) {
            this.pass(purchaseOrderDO.getPoCode(),CommonConstant.SYSTEM_AUTO_CREATE);
        }
    }




    public void checkPrAmount(PurchaseOrderDO purchaseOrderDO) {
        String prCode = purchaseOrderDO.getPrCode();
        List<PurchaseOrderDO> poList = purchaseOrderDAO.getByPrCode(prCode);
        poList = poList.stream()
                .filter(po -> AuditStatusEnum.getApprovalCodeList().contains(po.getAuditStatus()) || Objects.equals(po.getPoCode(), purchaseOrderDO.getPoCode()))
                .collect(Collectors.toList());
        //PR预算金额

        PurchaseRequisitionDO purchaseRequisitionDO = purchaseRequisitionDAO.getByPrCode(prCode);
        BigDecimal totalBudgetUsd = commonService.getUsdAmountV2(purchaseRequisitionDO.getSettlementCurrency(), purchaseRequisitionDO.getTotalBudget());

        BigDecimal totalTaxInclusivePurchaseAmountUsd = getPoAllAmountUsd(poList);
        PurchaseAssert.isTrue(DecimalUtils.getIntegerPart(totalTaxInclusivePurchaseAmountUsd) > DecimalUtils.getIntegerPart(totalBudgetUsd), ErrorCodeEnums.ALL_PO_AMOUNT_CANNOT_EXCEED_PR_BUDGET, prCode);
    }

    private BigDecimal getPoAllAmountUsd(List<PurchaseOrderDO> poList) {
        List<String> poCodeList = poList.stream()
                .map(PurchaseOrderDO::getPoCode)
                .distinct()
                .collect(Collectors.toList());
        List<String> contractCodeList = poList.stream().map(PurchaseOrderDO::getContractCode).distinct().collect(Collectors.toList());
        List<PurchaseContractInfoDO> contractList = purchaseContractInfoDAO.getByContractCodes(contractCodeList);
        Map<String, String> contractSupplierMap = contractList.stream().collect(Collectors.toMap(PurchaseContractInfoDO::getContractCode, PurchaseContractInfoDO::getSupplierCode, (v1, v2) -> v1));

        List<String> supplierCodeList = contractList.stream().map(PurchaseContractInfoDO::getSupplierCode).distinct().collect(Collectors.toList());
        List<SupplierFinancialBankRes> supplierFinancialBankResList = supplierCodeList.stream().map(sdsIntegration::getFinancialBankListByCode).flatMap(Collection::stream).collect(Collectors.toList());
        HashBasedTable<String, Integer, SupplierFinancialBankRes> supplierFinancialBankTable = supplierFinancialBankResList.stream().collect(Tables.toTable(
                SupplierFinancialBankRes::getSupplierCode,
                SupplierFinancialBankRes::getSiteNumber,
                item -> item,
                (v1, v2) -> v1,
                HashBasedTable::create
        ));
        return poCodeList.stream()
                .map(purchaseOrderManager::getOrderBO)
                .map(OrderBO::getPurchaseOrderDO)
                .filter(Objects::nonNull)
                .map(o -> {
                    String supplierCode = contractSupplierMap.get(o.getContractCode());
                    SupplierFinancialBankRes financialBank = supplierFinancialBankTable.get(supplierCode, o.getSiteNumber());
                    return commonService.getUsdAmountV2(financialBank.getSettlementCurrency(), o.getTotalTaxInclusiveAmount());
                })
                .reduce(DecimalUtils::add)
                .orElse(BigDecimal.ZERO);
    }

    public void checkContractAmount(PurchaseOrderDO purchaseOrderDO) {
        String contractCode = purchaseOrderDO.getContractCode();
        //根据PR号得到关联的审核中、审核通过的PO+本单
        List<PurchaseOrderDO> poList = purchaseOrderDAO.getByContractCode(contractCode);
        poList = poList.stream()
                .filter(po -> AuditStatusEnum.getApprovalCodeList().contains(po.getAuditStatus()) || Objects.equals(po.getPoCode(), purchaseOrderDO.getPoCode()))
                .collect(Collectors.toList());
        List<String> poCodeList = poList.stream()
                .map(PurchaseOrderDO::getPoCode)
                .distinct()
                .collect(Collectors.toList());
        PurchaseContractInfoDO contract = purchaseContractInfoDAO.getByContractCode(contractCode);
        BigDecimal totalContractAmountUsd = commonService.getUsdAmountV2(contract.getSettlementCurrency(), contract.getTotalContractAmount());
        List<SupplierFinancialBankRes> financialBankList = sdsIntegration.getFinancialBankListByCode(contract.getSupplierCode());
        Map<Integer, SupplierFinancialBankRes> financialBankMap = financialBankList.stream().collect(Collectors.toMap(SupplierFinancialBankRes::getSiteNumber, Function.identity(), (v1, v2) -> v1));
        BigDecimal totalTaxInclusivePurchaseAmountUsd = poCodeList.stream()
                .map(poCode -> {
                    OrderBO orderBO = purchaseOrderManager.getOrderBO(poCode);
                    return orderBO;
                })
                .map(OrderBO::getPurchaseOrderDO)
                .filter(Objects::nonNull)
                .map(o -> {
                    SupplierFinancialBankRes financialBank = financialBankMap.get(o.getSiteNumber());
                    return commonService.getUsdAmountV2(financialBank.getSettlementCurrency(), o.getTotalTaxInclusiveAmount());
                })
                .reduce(DecimalUtils::add)
                .orElse(BigDecimal.ZERO);
        PurchaseAssert.isTrue(DecimalUtils.getIntegerPart(totalTaxInclusivePurchaseAmountUsd) > DecimalUtils.getIntegerPart(totalContractAmountUsd), ErrorCodeEnums.PO_AMOUNT_CANNOT_EXCEED_CONTRACT_AMOUNT, contractCode);
    }


    public ApprovalInfoCreateResultDTO buildAndPushApproval(OrderBO orderBO,
                                                            PurchaseOrderDTO purchaseOrderDTO,
                                                            PurchaseRequisitionDO purchaseRequisitionDO) {
        //审批流内容封装
        PurchaseOrderDO purchaseOrderDO = orderBO.getPurchaseOrderDO();
        List<ApprovalTypeFieldApiDTO> param = getPoApprovalDTO(orderBO, purchaseRequisitionDO);
        ApprovalInitInfoApiBO approvalInitInfoApiBO = new ApprovalInitInfoApiBO();
        approvalInitInfoApiBO.setAuditCodeEnums(AuditCodeEnums.PURCHASE_ORDER_AUDIT);
        approvalInitInfoApiBO.setBusinessCode(purchaseOrderDTO.getPoCode());
        approvalInitInfoApiBO.setParam(param);
        String encodeUrl = UrlEncodeUtil.encode(String.format(poPageUrl, purchaseOrderDTO.getPoCode()));
        approvalInitInfoApiBO.setSrcBizPageUrl(encodeUrl);
        approvalInitInfoApiBO.setAppointApprovalCode(purchaseOrderDTO.getPoCode());
        //审批流调用
        //上一次审批如果是驳回，延续上次审批
        Long resubmitApprovalId = null;
        if (purchaseOrderDO.getApprovalInfoStatus() != null && ApprovalInfoStatusEnums.REJECT.getCode().equals(purchaseOrderDO.getApprovalInfoStatus())) {
            PurchaseOrderAuditDO lastAuditDO = purchaseOrderAuditDAO.getLastByPoCode(purchaseOrderDO.getPoCode());
            if (lastAuditDO != null) {
                resubmitApprovalId = Long.parseLong(lastAuditDO.getAuditCode());
                approvalInitInfoApiBO.setResubmitApprovalId(resubmitApprovalId);
                approvalInitInfoApiBO.setResubmitApprovalRemark(purchaseOrderDTO.getReSubmitApprovalRemark());
            }
        }
        //修改单据的跳转url（加密）
        String encodePoCode = Base64.encode(purchaseOrderDTO.getPoCode().getBytes());
        String amendBizPageUrl = UrlEncodeUtil.encode(poLinkPrefix + purchaseOrderDTO.getPoCode() + "&update=" + encodePoCode);
        approvalInitInfoApiBO.setAmendBizPageUrl(amendBizPageUrl);
        ApprovalInfoCreateResultDTO approval = null;
        try {
            approval = approvalIntegration.createApprovalWithBO(approvalInitInfoApiBO);
        } catch (Exception e) {
            log.error("approval fail error:" + purchaseOrderDO.getPoCode(), e);
            if (approval != null) {
                log.info("approval result {}, code is {}", JSON.toJSONString(approval),
                        approvalInitInfoApiBO.getAppointApprovalCode());
                approvalIntegration.backApproval(approval.getApprovalId().toString());
            }
            throw BusinessException.get(ErrorCodeEnums.CREATE_APPROVAL_ERROR.getCode(),
                    I18nUtils.getMessage(ErrorCodeEnums.CREATE_APPROVAL_ERROR.getDesc()));
        }
        return approval;
    }


