        taxInclusivePurchaseAmountList.add(purchaseOrderDO.getTotalTaxInclusiveAmount().setScale(4, BigDecimal.ROUND_HALF_UP).stripTrailingZeros().toPlainString());
        cumulativeReceiptQtyList.add("-");
        cumulativeReceiptAmountList.add("-");
        cumulativeTaxInclusiveReceiptAmountList.add("-");
        actualDeliveryDateList.add("-");
        purchaseRemarksList.add("-");

        param.add(approvalIntegration.buildApprovalTypeFieldApiDTO("itemCodeList", JSON.toJSONString(itemCodeList)));
        param.add(approvalIntegration.buildApprovalTypeFieldApiDTO("itemNameList", JSON.toJSONString(itemNameList)));
