        param.add(approvalIntegration.buildApprovalTypeFieldApiDTO("taxInclusivePriceList", JSON.toJSONString(taxInclusivePriceList)));
        param.add(approvalIntegration.buildApprovalTypeFieldApiDTO("taxRateList", JSON.toJSONString(taxRateList)));
        param.add(approvalIntegration.buildApprovalTypeFieldApiDTO("purchaseAmountList", JSON.toJSONString(purchaseAmountList)));
        param.add(approvalIntegration.buildApprovalTypeFieldApiDTO("taxInclusivePurchaseAmountList", JSON.toJSONString(taxInclusivePurchaseAmountList)));
        param.add(approvalIntegration.buildApprovalTypeFieldApiDTO("cumulativeReceiptQtyList", JSON.toJSONString(cumulativeReceiptQtyList)));
        param.add(approvalIntegration.buildApprovalTypeFieldApiDTO("cumulativeReceiptAmountList", JSON.toJSONString(cumulativeReceiptAmountList)));
