        if (purchaseOrderDO.getOneDeptId() != null && purchaseOrderDO.getTwoDeptId() != null) {
            param.add(approvalIntegration.buildApprovalTypeFieldApiDTO("deptId", purchaseOrderDO.getTwoDeptId().toString()));
        } else if (purchaseOrderDO.getOneDeptId() != null && purchaseOrderDO.getTwoDeptId() == null) {
            param.add(approvalIntegration.buildApprovalTypeFieldApiDTO("deptId", purchaseOrderDO.getOneDeptId().toString()));
