        //预付款到期时间
        LocalDateTime downPaymentWriteOffDate = purchaseOrderDO.getDownPaymentWriteOffDate();
        if (Objects.nonNull(downPaymentWriteOffDate)) {
            param.add(approvalIntegration.buildApprovalTypeFieldApiDTO("downPaymentWriteOffDate",
