     *
     * @return
     */
    private BigDecimal getPoTaxInclusiveAmount(HashMap<String, PurchaseOrderDetailDO> itemCodeAndPoDetailMap) {

        if (itemCodeAndPoDetailMap == null) {
            return null;
        }

        //有税率为null，采购含税金额为null
        Set<String> itemCodes = itemCodeAndPoDetailMap.keySet();
        for (String itemCode : itemCodes) {
            PurchaseOrderDetailDO purchaseOrderDetailDO = itemCodeAndPoDetailMap.get(itemCode);
            if (purchaseOrderDetailDO.getItemCodeTaxRate() == null) {
                return null;
            }
        }

        //计算PO采购含税金额
        BigDecimal totalTaxInclusiveAmount = new BigDecimal("0");
        for (String itemCode : itemCodes) {
            //Qty
            PurchaseOrderDetailDO purchaseOrderDetailDO = itemCodeAndPoDetailMap.get(itemCode);
            BigDecimal purchaseQty = purchaseOrderDetailDO.getPurchaseQty();
            //Price
            BigDecimal price = purchaseOrderDetailDO.getPrice();
            //TaxInclusiveAmount
            if (purchaseOrderDetailDO.getPurchaseQty() != null) {
                BigDecimal amount = purchaseQty.multiply(price);
                if (purchaseOrderDetailDO.getItemCodeTaxRate() != null) {
                    BigDecimal taxInclusiveAmount = amount.multiply(new BigDecimal("1").add(purchaseOrderDetailDO.getItemCodeTaxRate()));
                    totalTaxInclusiveAmount = totalTaxInclusiveAmount.add(taxInclusiveAmount);
                }
            }
        }

        return totalTaxInclusiveAmount;
    }

    /**
     * PO采购金额
     *
     * @return
     */
    private BigDecimal getPoPurchaseAmount(HashMap<String, PurchaseOrderDetailDO> itemCodeAndPoDetailMap) {

        Set<String> itemCodes = itemCodeAndPoDetailMap.keySet();
        BigDecimal totalPurchaseAmount = new BigDecimal("0");
        for (String itemCode : itemCodes) {
            //Qty
            PurchaseOrderDetailDO purchaseOrderDetailDO = itemCodeAndPoDetailMap.get(itemCode);
            BigDecimal purchaseQty = purchaseOrderDetailDO.getPurchaseQty();
            //Price
            BigDecimal price = purchaseOrderDetailDO.getPrice();
            //Amount
            BigDecimal amount = purchaseQty.multiply(price);
            totalPurchaseAmount = totalPurchaseAmount.add(amount);
        }

        return totalPurchaseAmount;
    }


