    /**
     * PO列表（分页+条件）V2
     *
     * @param poPageQuery
     * @return
     */
    @Override
    @Transactional
    public PaginationResult<PurchaseOrderPageVO> page(PurchaseOrderPageQuery poPageQuery) {

        poPageQuery.dealDocumentCode();
        //筛选条件转换
        List<String> contractCodeList = null;
        List<String> prCodeList = null;
        //供应商\采购组织 转化为contractCodeList
        if (CollectionUtils.isNotEmpty(poPageQuery.getSupplierCodeList()) || poPageQuery.getPurchaseOrgId() != null) {
            List<PurchaseContractInfoDO> purchaseContractInfoDOS = purchaseContractInfoDAO.getPassByQuery(poPageQuery);
            if (CollectionUtils.isEmpty(purchaseContractInfoDOS)) {
                return PaginationResult.get(new ArrayList<>(), poPageQuery);
            }
            contractCodeList = purchaseContractInfoDOS.stream().map(PurchaseContractInfoDO::getContractCode).collect(Collectors.toList());
        }
        //采购品类\采购员 转化为prCodeList
        if (StringUtils.isNotBlank(poPageQuery.getCategorySubtypeCode())) {
            List<PurchaseRequisitionDO> purchaseRequisitionDOS = purchaseRequisitionDAO.getPassByQuery(poPageQuery);
            if (CollectionUtils.isEmpty(purchaseRequisitionDOS)) {
                return PaginationResult.get(new ArrayList<>(), poPageQuery);
            }
            prCodeList = purchaseRequisitionDOS.stream().map(PurchaseRequisitionDO::getPrCode).collect(Collectors.toList());
        }
        poPageQuery.setContractCodeList(contractCodeList);
        poPageQuery.setPrCodeList(prCodeList);


        //根据itemCodeList填充poCodeList
        List<String> itemPoCodeList = itemCodeListBuildPoCodeList(poPageQuery);
        log.info("PurchaseOrderManagerServiceImpl | page | queryPage | poPageQuery={}", poPageQuery);
        if (CollectionUtils.isNotEmpty(poPageQuery.getItemCodeList()) && CollectionUtils.isEmpty(itemPoCodeList)) {
            return PaginationResult.get(new ArrayList<>(), poPageQuery);
        }
        //权限
        List<String> permissionCodeList = permissionService.getPermissionCodeList(UcenterUtils.getUserInfo().getUserCode(), PurchaseDocumentEnum.PO, poPageQuery.getPoCodeList());
        if (CollectionUtils.isEmpty(permissionCodeList)) {
            return PaginationResult.get(new ArrayList<>(), poPageQuery);
        }
        poPageQuery.setPoCodeList(permissionCodeList);
        Page<Object> page = PageMethod.startPage(poPageQuery.getCurrentPage(), poPageQuery.getShowCount());
        List<PurchaseOrderDO> purchaseOrderDOS = purchaseOrderDAO.queryPage(poPageQuery);
        if (CollectionUtils.isEmpty(purchaseOrderDOS)) {
            return PageUtil.get(new ArrayList(), page, poPageQuery);
        }

        List<String> contractCodes = new ArrayList<>();
        List<String> prCodes = new ArrayList<>();
        List<String> poCodes = new ArrayList<>();
        List<String> personCodes = new ArrayList<>();
        List<Long> deptIds = new ArrayList<>();

        purchaseOrderDOS.stream().forEach(purchaseOrderDO -> {
            if (StringUtils.isNotBlank(purchaseOrderDO.getContractCode())) {
                contractCodes.add(purchaseOrderDO.getContractCode());
            }
            prCodes.add(purchaseOrderDO.getPrCode());
            poCodes.add(purchaseOrderDO.getPoCode());
            if (StringUtils.isNotBlank(purchaseOrderDO.getBuyerCode())) {
                personCodes.add(purchaseOrderDO.getBuyerCode());
            }
            if (purchaseOrderDO.getOneDeptId() != null) {
                deptIds.add(purchaseOrderDO.getOneDeptId());
            }
            if (purchaseOrderDO.getTwoDeptId() != null) {
                deptIds.add(purchaseOrderDO.getTwoDeptId());
            }
        });

        List<PurchaseOrderAuditDO> poAuditList = purchaseOrderAuditDAO.getByPoCodeList(poCodes);
        Map<String, PurchaseOrderAuditDO> auditMap = poAuditList.stream()
                .collect(Collectors.toMap(PurchaseOrderAuditDO::getPoCode,
                        Function.identity(),
                        (v1, v2) -> v1.getCreateDate().isAfter(v2.getCreateDate()) ? v1 : v2));

        List<PurchaseContractInfoDO> purchaseContractInfoDOSList = purchaseContractInfoDAO.getByContractCodes(contractCodes);
        List<PurchaseRequisitionDO> purchaseRequisitionDOList = purchaseRequisitionDAO.getByPrCodes(prCodes);
        Map<String, PurchaseContractInfoDO> contractInfoDOMap = purchaseContractInfoDOSList.stream().collect(Collectors.toMap(PurchaseContractInfoDO::getContractCode, Function.identity(), (k, v) -> k));
        Map<String, PurchaseRequisitionDO> purchaseRequisitionDOMap = purchaseRequisitionDOList.stream().collect(Collectors.toMap(PurchaseRequisitionDO::getPrCode, Function.identity(), (k, v) -> k));

        List<String> categoryCodes = new ArrayList<>();
        purchaseRequisitionDOList.stream().forEach(purchaseRequisitionDO -> {
            categoryCodes.add(purchaseRequisitionDO.getCategorySubtypeCode());
        });
        //封装Map<品类编码，品类名称>
        HashMap<String, String> categoryMap = new HashMap<>();
        List<SupplierCategoryDO> categoryDOS = supplierCategoryDAO.listCategory(categoryCodes);
        for (SupplierCategoryDO categoryDO : categoryDOS) {
            if (Locale.CHINA.equals(UserEvnHolder.getLocal())) {
                categoryMap.put(categoryDO.getCategorySubtypeCode(), categoryDO.getCategorySubtypeNameChn());
            } else {
                categoryMap.put(categoryDO.getCategorySubtypeCode(), categoryDO.getCategorySubtypeNameEn());
            }
        }
        //封装Map<关联合同号，付款条件>
        HashMap<String, String> contractRedemptionPeriodMap = purchaseContractRedemptionPeriodDAO.getPaymentTermByContractCodes(contractCodes);
        //Map<合同号，Map<采购编码，合同报价>>
        List<PurchaseContractDetailPriceSettingDO> priceSettingDOS = purchaseContractDetailPriceSettingDAO.getByContractCodes(contractCodes);
        Map<String, List<PurchaseContractDetailPriceSettingDO>> priceMap = priceSettingDOS.stream().collect(Collectors.groupingBy(PurchaseContractDetailPriceSettingDO::getContractCode));

        List<PurchaseContractDetailDO> detailByContractCodes = purchaseContractDetailDAO.getDetailByContractCodes(contractCodes);
        Map<String, List<PurchaseContractDetailDO>> purchaseContractDetailDOMp = detailByContractCodes.stream().collect(Collectors.groupingBy(PurchaseContractDetailDO::getContractCode));
        //封装Map<PO号，关联RI集合>\Map<RI号，RIdetail集合>
        HashMap<String, List<PurchaseReceiptDO>> riMap = new HashMap<>();
        HashMap<String, List<PurchaseReceiptDetailDO>> riDetailMap = new HashMap<>();
        List<PurchaseReceiptDO> purchaseReceiptDOS = purchaseReceiptDAO.getByPoCodes(poCodes);
        if (CollectionUtils.isNotEmpty(purchaseReceiptDOS)) {
            //Map<PO号，关联RI集合>
            riMap = purchaseReceiptDAO.getRiMap(purchaseReceiptDOS);
            List<String> riCodes = purchaseReceiptDOS.stream().map(PurchaseReceiptDO::getPurchaseReceiptCode).distinct().collect(Collectors.toList());
            //Map<RI号，RIdetail集合>
            riDetailMap = purchaseReceiptDetailDAO.getRiDetailMap(riCodes);
        }
        //Map<PO号，Map<采购编码，累计验收数量(审核中、审核通过)>>
        List<PurchaseReceiptDO> submitOrPassPurchaseReceiptDOS = purchaseReceiptDOS.stream().filter(item -> SupplierDataStatusEnums.PASS.getCode().equals(item.getAuditStatus()) || SupplierDataStatusEnums.SUBMIT.getCode().equals(item.getAuditStatus())).collect(Collectors.toList());
        List<String> submitOrPassPurchaseReceiptCodeList = submitOrPassPurchaseReceiptDOS.stream().map(PurchaseReceiptDO::getPurchaseReceiptCode).collect(Collectors.toList());
        List<PurchaseReceiptDetailDO> submitOrPassPurchaseReceiptDetailDOList = purchaseReceiptDetailDAO.getByRiCodes(submitOrPassPurchaseReceiptCodeList);
        Map<String, List<PurchaseReceiptDetailDO>> purchaseReceiptDetailDOMap = emptyIfNull(submitOrPassPurchaseReceiptDetailDOList).stream().collect(Collectors.groupingBy(PurchaseReceiptDetailDO::getPurchaseReceiptCode));

        //人员、部门Map封装
        HashMap<String, String> personMap = hrmsService.getUserMap(personCodes);
        Map<Long, String> deptMap = hrmsService.getDeptMap(deptIds);
        //采购组织Map封装
        ArrayList<Long> purchaseOrgIds = new ArrayList<>();
        purchaseContractInfoDOSList.stream().forEach(item -> {
            if (item.getContractOrgId() != null) {
                purchaseOrgIds.add(item.getContractOrgId());
            }
        });
        HashMap<Long, String> orgMap = hrmsService.getOrgMap(purchaseOrgIds);
        Map<String, List<OrderBO.PurchaseOrderDetailBO>> purchaseOrderDetailBOMap = purchaseOrderManager.getPurchaseOrderDetailBOMap(poCodes);

        //列表返回值封装
        List<PurchaseOrderPageVO> purchaseOrderPageVOS = new ArrayList<>();
        for (PurchaseOrderDO purchaseOrderDO : purchaseOrderDOS) {
            PurchaseOrderPageVO purchaseOrderPageVO = new PurchaseOrderPageVO();
            BeanUtils.copyProperties(purchaseOrderDO, purchaseOrderPageVO);
            //审批流Code
            PurchaseOrderAuditDO poAudit = auditMap.getOrDefault(purchaseOrderDO.getPoCode(), new PurchaseOrderAuditDO());
            purchaseOrderPageVO.setAuditCode(poAudit.getAuditCode());

            purchaseOrderPageVO.setDownPaymentWriteOffDate(DateTimeUtils.nullIfEqualToDefault(purchaseOrderDO.getDownPaymentWriteOffDate()));
            ////PR带出
            PurchaseRequisitionDO purchaseRequisitionDO = purchaseRequisitionDOMap.get(purchaseOrderDO.getPrCode());
            if (purchaseRequisitionDO != null) {
                //品类名称
                String categoryName = categoryMap.get(purchaseRequisitionDO.getCategorySubtypeCode());
                purchaseOrderPageVO.setCategorySubtypeName(categoryName);
            }

            //一二级部门名称封装
            String oneDeptName = deptMap.get(purchaseOrderDO.getOneDeptId());
            String twoDeptName = deptMap.get(purchaseOrderDO.getTwoDeptId());
            if (StringUtils.isNotBlank(twoDeptName)) {
                purchaseOrderPageVO.setOneTwoDeptName(twoDeptName);
            } else if (StringUtils.isNotBlank(oneDeptName) && StringUtils.isBlank(twoDeptName)) {
                purchaseOrderPageVO.setOneTwoDeptName(oneDeptName);
            }

            //采购员
            purchaseOrderPageVO.setBuyerName(personMap.get(purchaseOrderDO.getBuyerCode()));
            //关联PR号
            purchaseOrderPageVO.setAssociatedPr(purchaseOrderDO.getPrCode());

            ////合同带出
            PurchaseContractInfoDO purchaseContractInfoDO = contractInfoDOMap.get(purchaseOrderDO.getContractCode());
            //关联合同后才会封装的字段：采购组织、供应商、采购数量、采购金额、含税金额、累计验收数量、累计验收金额、累计验收含税金额
            //币种、税率、付款条件、关联合同号、关联验收单号
            if (StringUtils.isNotBlank(purchaseOrderDO.getContractCode())) {
                //mainContractCode
                purchaseOrderPageVO.setMainContractCode(purchaseContractInfoDO.getMainContractCode());
                //采购组织、供应商、币种、关联合同号
                purchaseOrderPageVO.setPurchaseOrgName(orgMap.get(purchaseContractInfoDO.getContractOrgId()));
                //注意：使用全称，填充页面
                purchaseOrderPageVO.setSupplierShortName(purchaseContractInfoDO.getSupplierName());
                purchaseOrderPageVO.setSupplierCode(purchaseContractInfoDO.getSupplierCode());
                purchaseOrderPageVO.setSettlementCurrency(purchaseContractInfoDO.getSettlementCurrency());
                purchaseOrderPageVO.setAssociatedContract(purchaseOrderDO.getContractCode());
                //税率转换成%
                purchaseOrderPageVO.setTaxRate(purchaseContractInfoDO.getDefaultTaxRate().multiply(new BigDecimal("100")).setScale(2, BigDecimal.ROUND_HALF_UP));
                //采购数量（总）、采购金额（总）、含税金额（总）、累计验收数量、累计验收金额、累计验收含税金额
                List<PurchaseContractDetailPriceSettingDO> contractDetailPriceSettingList = priceMap.get(purchaseContractInfoDO.getContractCode());
                List<PurchaseContractDetailDO> detailDOList = purchaseContractDetailDOMp.get(purchaseContractInfoDO.getContractCode());
                List<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOS = purchaseOrderDetailBOMap.get(purchaseOrderDO.getPoCode());
                List<OrderItemBO> orderItemBOList;
                if (AuditStatusEnum.getUnSubmitList().contains(SafeEnumUtil.getBy(AuditStatusEnum::getCode, purchaseOrderDO.getAuditStatus()))) {
                    orderItemBOList = handleItemAmount(purchaseOrderDO.getItemInputMode(),purchaseOrderDetailBOS, detailDOList, contractDetailPriceSettingList);
                } else {
                    orderItemBOList = handleItemAmount(purchaseOrderDO.getItemInputMode(),purchaseOrderDetailBOS);
                }
                BigDecimal totalPurchaseAmount = orderItemBOList.stream().filter(Objects::nonNull).map(OrderItemBO::getAmountExcludingTax).reduce(BigDecimal.ZERO, DecimalUtils::add);
                BigDecimal totalTaxInclusiveAmount = orderItemBOList.stream().filter(Objects::nonNull).map(OrderItemBO::getAmountIncludingTax).reduce(BigDecimal.ZERO, DecimalUtils::add);
                BigDecimal totalPurchaseQty = purchaseOrderDetailBOS.stream().map(OrderBO.PurchaseOrderDetailBO::getPurchaseOrderDetailDO).map(PurchaseOrderDetailDO::getPurchaseQty).reduce(BigDecimal.ZERO, DecimalUtils::add);
                purchaseOrderPageVO.setTotalPurchaseQty(totalPurchaseQty);
                purchaseOrderPageVO.setTotalPurchaseAmount(totalPurchaseAmount);
                purchaseOrderPageVO.setTotalTaxInclusiveAmount(totalTaxInclusiveAmount);

                List<PurchaseReceiptDO> associatedReceiptDOS = riMap.get(purchaseOrderDO.getPoCode());
                List<PurchaseReceiptDetailDO> receiptDetailDOList = emptyIfNull(associatedReceiptDOS).stream()
                        .map(PurchaseReceiptDO::getPurchaseReceiptCode)
                        .map(purchaseReceiptDetailDOMap::get)
                        .filter(Objects::nonNull)
                        .flatMap(Collection::stream)
                        .collect(Collectors.toList());
                Map<String, OrderItemBO> receiptPriceMap = getReceiptPriceMap(purchaseOrderDO.getItemInputMode(), purchaseOrderDetailBOS, receiptDetailDOList);
                List<OrderItemBO> cumulativeReceiptItemBOList = new ArrayList<>(receiptPriceMap.values());
                BigDecimal cumulativeReceiptQty = cumulativeReceiptItemBOList.stream().filter(Objects::nonNull).map(OrderItemBO::getQty).reduce(BigDecimal.ZERO, DecimalUtils::add);
                BigDecimal cumulativeReceiptAmount = cumulativeReceiptItemBOList.stream().filter(Objects::nonNull).map(OrderItemBO::getAmountExcludingTax).reduce(BigDecimal.ZERO, DecimalUtils::add);
                BigDecimal cumulativeTaxInclusiveReceiptAmount = cumulativeReceiptItemBOList.stream().filter(Objects::nonNull).map(OrderItemBO::getAmountIncludingTax).reduce(BigDecimal.ZERO, DecimalUtils::add);
                purchaseOrderPageVO.setCumulativeReceiptQty(cumulativeReceiptQty);
                purchaseOrderPageVO.setCumulativeReceiptAmount(cumulativeReceiptAmount.setScale(4, BigDecimal.ROUND_HALF_UP));
                purchaseOrderPageVO.setCumulativeTaxInclusiveReceiptAmount(cumulativeTaxInclusiveReceiptAmount.setScale(4, BigDecimal.ROUND_HALF_UP));
            }

            //付款条件
            String paymentTerm = contractRedemptionPeriodMap.get(purchaseOrderDO.getContractCode());
            if (StringUtils.isNotBlank(paymentTerm)) {
                purchaseOrderPageVO.setPaymentTerm(paymentTerm.substring(0, paymentTerm.length() - 1));
            }
            //关联验收单列表
            List<AssociatedPurchaseReceiptVO> associatedPurchaseReceiptVOS = new ArrayList<>();
            List<PurchaseReceiptDO> associatedReceiptDOS = riMap.get(purchaseOrderDO.getPoCode());
            if (CollectionUtils.isNotEmpty(associatedReceiptDOS)) {
                for (PurchaseReceiptDO associatedReceiptDO : associatedReceiptDOS) {
                    AssociatedPurchaseReceiptVO associatedPurchaseReceiptVO = new AssociatedPurchaseReceiptVO();
                    BeanUtils.copyProperties(associatedReceiptDO, associatedPurchaseReceiptVO);
                    associatedPurchaseReceiptVO.setSupplierShortName(purchaseContractInfoDO.getSupplierShortName());
                    //单个RI的累计验收数量、累计验收金额、累计验收含税金额
                    List<PurchaseReceiptDetailDO> receiptDetailDOList = riDetailMap.get(associatedReceiptDO.getPurchaseReceiptCode());
                    BigDecimal totalReceiptQty = new BigDecimal("0");
                    if (CollectionUtils.isNotEmpty(receiptDetailDOList)) {
                        for (PurchaseReceiptDetailDO purchaseReceiptDetailDO : receiptDetailDOList) {
                            BigDecimal receiptQty = purchaseReceiptDetailDO.getReceiptQty();
                            totalReceiptQty = totalReceiptQty.add(receiptQty);
                        }
                    }
                    associatedPurchaseReceiptVO.setTotalReceiptQty(totalReceiptQty);
                    associatedPurchaseReceiptVO.setTotalTaxInclusiveReceiptAmount(associatedReceiptDO.getTotalTaxInclusiveReceiptAmount());
                    associatedPurchaseReceiptVOS.add(associatedPurchaseReceiptVO);
                }
                purchaseOrderPageVO.setAssociatedRiList(associatedPurchaseReceiptVOS);
            }

            purchaseOrderPageVOS.add(purchaseOrderPageVO);
        }

        return PageUtil.get(purchaseOrderPageVOS, page, poPageQuery);
    }

    /**
     * Map<PO号，Map<采购编码，累计验收数量(审核中、审核通过)>>
     *
     * @param submitOrPassPurchaseReceiptDOS
     * @return
     */
    private Map<String, Map<String, BigDecimal>> getCumulativeReceiptQtyMap(List<String> poCodes, List<PurchaseReceiptDO> submitOrPassPurchaseReceiptDOS) {

        if (CollectionUtils.isEmpty(poCodes) || CollectionUtils.isEmpty(submitOrPassPurchaseReceiptDOS)) {
            return new HashMap<>();
        }

        Map<String, List<PurchaseReceiptDO>> poCodeAndReceiptDOSMap = submitOrPassPurchaseReceiptDOS.stream().collect(Collectors.groupingBy(PurchaseReceiptDO::getPoCode));
        List<String> riCodes = submitOrPassPurchaseReceiptDOS.stream().map(PurchaseReceiptDO::getPurchaseReceiptCode).collect(Collectors.toList());
        List<PurchaseReceiptDetailDO> submitOrPassRiDetailDOS = purchaseReceiptDetailDAO.getByRiCodes(riCodes);

        HashMap<String, Map<String, BigDecimal>> cumulativeReceiptQtyMap = new HashMap<>();
        for (String poCode : poCodes) {
            HashMap<String, BigDecimal> itemCodeAndCumulativeReceiptQtyMap = new HashMap<>();
            List<PurchaseReceiptDO> purchaseReceiptDOS = poCodeAndReceiptDOSMap.get(poCode);
            if (CollectionUtils.isNotEmpty(purchaseReceiptDOS)) {
                List<String> riCodeList = purchaseReceiptDOS.stream().map(PurchaseReceiptDO::getPurchaseReceiptCode).collect(Collectors.toList());
                List<PurchaseReceiptDetailDO> purchaseReceiptDetailDOS = submitOrPassRiDetailDOS.stream().filter(item -> riCodeList.contains(item.getPurchaseReceiptCode())).collect(Collectors.toList());

                for (PurchaseReceiptDetailDO purchaseReceiptDetailDO : purchaseReceiptDetailDOS) {
                    BigDecimal itemCodeCumulativeReceiptQty = itemCodeAndCumulativeReceiptQtyMap.get(purchaseReceiptDetailDO.getPurchaseItemCode());
                    if (itemCodeCumulativeReceiptQty == null) {
                        itemCodeCumulativeReceiptQty = new BigDecimal("0");
                    }
                    if (purchaseReceiptDetailDO.getReceiptQty() != null) {
                        itemCodeCumulativeReceiptQty = itemCodeCumulativeReceiptQty.add(purchaseReceiptDetailDO.getReceiptQty());
                    }
                    itemCodeAndCumulativeReceiptQtyMap.put(purchaseReceiptDetailDO.getPurchaseItemCode(), itemCodeCumulativeReceiptQty);
                }

            }

            cumulativeReceiptQtyMap.put(poCode, itemCodeAndCumulativeReceiptQtyMap);
        }

        return cumulativeReceiptQtyMap;
    }

    @Override
    @Transactional
    public String recallFromBpm(String poCode) {
        PurchaseOrderDO purchaseOrderDO = purchaseOrderDAO.getByPoCode(poCode);
        if (purchaseOrderDO == null) {
            throw BusinessException.get(ErrorCodeEnums.DATA_NOT_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.DATA_NOT_EXIST.getDesc()));
        }
        //判断是否可撤销
        if (!AuditStatusEnum.getCanReCallList().contains(purchaseOrderDO.getAuditStatus())) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_ORDER_CANNOT_RECALL.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_ORDER_CANNOT_RECALL.getDesc()));
        }

        //修改 PO表的审核状态
        List<PurchaseOrderAuditDO> purchaseOrderAuditDOS = purchaseOrderAuditDAO.getByPoCode(poCode);
        List<PurchaseOrderAuditDO> rejectRecords = purchaseOrderAuditDOS.stream().filter(DO -> SupplierDataStatusEnums.REJECT.getCode().equals(DO.getAuditStatus())).collect(Collectors.toList());
        if (CollectionUtils.isEmpty(rejectRecords)) {//没有审核不通过的记录
            purchaseOrderDO.setAuditStatus(SupplierDataStatusEnums.SAVE.getCode());
        } else {//有审核不通过的记录
            purchaseOrderDO.setAuditStatus(SupplierDataStatusEnums.REJECT.getCode());
        }
        purchaseOrderDO.setApprovalInfoStatus(ApprovalInfoStatusEnums.RECALL.getCode());
        BaseDOUtil.updateDO(purchaseOrderDO);
        purchaseOrderDAO.updateById(purchaseOrderDO);

        //逻辑删除 PO审核记录
        PurchaseOrderAuditDO lastPoAuditDO = purchaseOrderAuditDOS.stream().sorted(Comparator.comparing(PurchaseOrderAuditDO::getLastUpdDate).reversed())
                .collect(Collectors.collectingAndThen(Collectors.toList(), DO -> DO.get(0)));
        lastPoAuditDO.setIsDelete(CommonConstant.Y);
        BaseDOUtil.updateDO(lastPoAuditDO);
        purchaseOrderAuditDAO.updateById(lastPoAuditDO);
        return lastPoAuditDO.getAuditCode();
    }

    /**
     * PO复制
     *
     * @param oldPoCode
     * @return
     */
    @Override
    public String copyPo(String oldPoCode) {
        PurchaseOrderDO oldPurchaseOrderDO = purchaseOrderDAO.getByPoCode(oldPoCode);
        //复制校验：PO存在、关联PR存在且未完结、关联合同没过期，才可复制
        if (oldPurchaseOrderDO == null) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getDesc()));
        }
        PurchaseRequisitionDO purchaseRequisitionDO = purchaseRequisitionDAO.getByPrCode(oldPurchaseOrderDO.getPrCode());
        if (purchaseRequisitionDO == null || CompleteStatusEnums.COMPLETED.getCode().equals(purchaseRequisitionDO.getCompleteStatus())) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_REQUISITION_ALREADY_END.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_REQUISITION_ALREADY_END.getDesc()));
        }
        PurchaseContractInfoDO purchaseContractInfoDO = null;
        if (StringUtils.isNotBlank(oldPurchaseOrderDO.getContractCode())) {
            purchaseContractInfoDO = purchaseContractInfoDAO.getByContractCode(oldPurchaseOrderDO.getContractCode());
            if (purchaseContractInfoDO == null || LocalDateTime.now().isAfter(purchaseContractInfoDO.getCutOffDate())) {
                throw BusinessException.get(ErrorCodeEnums.CONTRACT_EXPIRED.getCode(), I18nUtils.getMessage(ErrorCodeEnums.CONTRACT_EXPIRED.getDesc()));
            }
        }

        String newPoCode = serialService.createPurchaseOrderCode();

        //新增 PO表
        buildNewPo(newPoCode, oldPurchaseOrderDO, purchaseRequisitionDO, purchaseContractInfoDO);

        //新增 PO的detail表
        List<PurchaseOrderDetailDO> oldPurchaseOrderDetailDOS = purchaseOrderDetailDAO.getByPoCode(oldPoCode);
        if (CollectionUtils.isNotEmpty(oldPurchaseOrderDetailDOS)) {
            List<PurchaseOrderDetailDO> newPurchaseOrderDetailDOS = oldPurchaseOrderDetailDOS.stream().map(item -> {
                PurchaseOrderDetailDO newPurchaseOrderDetailDO = new PurchaseOrderDetailDO();
                BeanUtils.copyProperties(item, newPurchaseOrderDetailDO);
                newPurchaseOrderDetailDO.setId(IdWorkerUtil.getId());
                newPurchaseOrderDetailDO.setPoCode(newPoCode);
                newPurchaseOrderDetailDO.setPurchaseQty(null);
                BaseDOUtil.insertDO(newPurchaseOrderDetailDO);
                return newPurchaseOrderDetailDO;
            }).collect(Collectors.toList());

            purchaseOrderDetailDAO.saveBatch(newPurchaseOrderDetailDOS);
        }

        //新增 PO费用分摊
        List<PurchaseOrderBudgetAllocationDO> oldBudgetAllocationDOS = purchaseOrderBudgetAllocationDAO.getByPoCode(oldPoCode);
        if (CollectionUtils.isNotEmpty(oldBudgetAllocationDOS)) {
            List<PurchaseOrderBudgetAllocationDO> newBudgetAllocationDOS = oldBudgetAllocationDOS.stream().map(item -> {
                PurchaseOrderBudgetAllocationDO purchaseOrderBudgetAllocationDO = new PurchaseOrderBudgetAllocationDO();
                BeanUtils.copyProperties(item, purchaseOrderBudgetAllocationDO);
                purchaseOrderBudgetAllocationDO.setId(IdWorkerUtil.getId());
                purchaseOrderBudgetAllocationDO.setPoCode(newPoCode);
                BaseDOUtil.insertDO(purchaseOrderBudgetAllocationDO);
                return purchaseOrderBudgetAllocationDO;
            }).collect(Collectors.toList());

            purchaseOrderBudgetAllocationDAO.saveBatch(newBudgetAllocationDOS);
        }

        return newPoCode;

    }

