        //校验必填项
        String message = ValidationUtil.validate(purchaseOrderDTO, UpdateApproval.class);
        if (StringUtils.isNotBlank(message)) {
            throw BusinessException.get(MsgCodeConstant.PARAM_INVALID, message);
        }

