    /**
     * 一次性刷数据接口：PO金额
     * 按照老逻辑刷 直接用PO明细表price*qty
     * purchase_order：total_purchase_amount采购金额、total_tax_inclusive_amount采购含税金额
     * purchase_order_detail：purchase_amount采购编码的采购金额、tax_inclusive_amount采购编码的采购含税金额
     *
     * @return
     */
    @Override
    @Transactional
    public void purchaseAmount() {
        List<PurchaseOrderDO> allPo = purchaseOrderDAO.getAllPo();

        List<String> poCodeList = allPo.stream().map(PurchaseOrderDO::getPoCode).collect(Collectors.toList());

        List<PurchaseOrderDetailDO> purchaseOrderDetailDOList = purchaseOrderDetailDAO.getByPoCodes(poCodeList);
        Map<String, List<PurchaseOrderDetailDO>> poCodeAndDetailMap = purchaseOrderDetailDOList.stream().collect(Collectors.groupingBy(PurchaseOrderDetailDO::getPoCode));

        for (PurchaseOrderDO purchaseOrderDO : allPo) {

            BigDecimal totalPurchaseAmount = new BigDecimal("0");
            BigDecimal totalTaxInclusivePurchaseAmount = new BigDecimal("0");

            List<PurchaseOrderDetailDO> purchaseOrderDetailDOS = poCodeAndDetailMap.get(purchaseOrderDO.getPoCode());
            if (CollectionUtils.isEmpty(purchaseOrderDetailDOS)) {
                continue;
            }

            for (PurchaseOrderDetailDO purchaseOrderDetailDO : purchaseOrderDetailDOS) {
                BigDecimal price = purchaseOrderDetailDO.getPrice();
                BigDecimal purchaseQty = purchaseOrderDetailDO.getPurchaseQty();
                BigDecimal itemCodeTaxRate = purchaseOrderDetailDO.getItemCodeTaxRate();
                if (price != null && purchaseQty != null) {
                    BigDecimal itemCodePurchaseAmount = price.multiply(purchaseQty);
                    purchaseOrderDetailDO.setPurchaseAmount(itemCodePurchaseAmount.setScale(4, BigDecimal.ROUND_HALF_UP));
                    totalPurchaseAmount = totalPurchaseAmount.add(itemCodePurchaseAmount);

                    if (itemCodeTaxRate != null) {
                        BigDecimal itemCodeTaxInclusivePurchaseAmount = itemCodePurchaseAmount.multiply(new BigDecimal("1").add(purchaseOrderDetailDO.getItemCodeTaxRate()));
                        purchaseOrderDetailDO.setTaxInclusiveAmount(itemCodeTaxInclusivePurchaseAmount.setScale(4, BigDecimal.ROUND_HALF_UP));
                        totalTaxInclusivePurchaseAmount = totalTaxInclusivePurchaseAmount.add(itemCodeTaxInclusivePurchaseAmount);
                    }
                }
            }

            purchaseOrderDO.setTotalPurchaseAmount(totalPurchaseAmount.setScale(4, BigDecimal.ROUND_HALF_UP));
            purchaseOrderDO.setTotalTaxInclusiveAmount(totalTaxInclusivePurchaseAmount.setScale(4, BigDecimal.ROUND_HALF_UP));
        }


        purchaseOrderDAO.updateBatchById(allPo);
        purchaseOrderDetailDAO.updateBatchById(purchaseOrderDetailDOList);


    }

