    @Override
    public PaginationResult<PurchaseOrderItemDetailExportVO> getPOItemDetailExport(PurchaseOrderVoucherExportQuery voucherExportQuery) {
        log.info("PurchaseOrderManagerServiceImpl | getPOItemDetailExport | start | voucherExportQuery={}", voucherExportQuery);
        List<String> checkPoCodeList = voucherExportQuery.getCheckPoCodeList();
        if (ObjectUtil.isNotEmpty(checkPoCodeList)) {
            voucherExportQuery.setPoCodeList(checkPoCodeList);
        }
        //校验itemCodeList个数
        commonService.maxItemCodeCount(voucherExportQuery.getItemCodeList());
        PaginationResult<PurchaseOrderPageVO> page = page(voucherExportQuery);
        List<PurchaseOrderPageVO> poList = page.getResults();
        if (ObjectUtil.isEmpty(poList)) {
            return PaginationResult.get(new ArrayList<>(), voucherExportQuery);
        }
        // poCode 列表
        List<String> poCodeList = poList.stream().map(PurchaseOrderPageVO::getPoCode).collect(Collectors.toList());
        // 全部明细数据
        List<PurchaseOrderDetailDO> purchaseOrderDetailList = purchaseOrderDetailDAO.getByPoCodes(poCodeList);
        // 明细数据Map <poCode,明细信息>
        Map<String, List<PurchaseOrderDetailDO>> purchaseOrderDetailMap = purchaseOrderDetailList.stream()
                .collect(Collectors.groupingBy(PurchaseOrderDetailDO::getPoCode));
        // Map <采购编码,采购编码表信息>
        List<String> itemCodeList = purchaseOrderDetailList.stream()
                .map(PurchaseOrderDetailDO::getPurchaseItemCode).collect(Collectors.toList());
        HashMap<String, PurchaseItemCodeDO> itemCodeMap = purchaseItemCodeDAO.getItemCodeMap(itemCodeList);
        // 获取关联合同 associatedContract，原来的 contractCode
        List<String> associatedContractList = poList.stream()
                .map(PurchaseOrderPageVO::getAssociatedContract).collect(Collectors.toList());
        // Map<合同编号,Map<采购编码，合同价>>
        Map<String, Map<String, List<PurchaseContractDetailPriceSettingDO>>> contractCodeItemCodePriceMap = ListMapConverter.listGroupBy(purchaseContractDetailPriceSettingDAO.getByContractCodes(associatedContractList), PurchaseContractDetailPriceSettingDO::getContractCode, PurchaseContractDetailPriceSettingDO::getItemCode);
        List<PurchaseContractDetailDO> purchaseContractDetailDOList = purchaseContractDetailDAO.getDetailByContractCodes(associatedContractList);
        HashBasedTable<String, String, PurchaseContractDetailDO> purchaseContractDetailDOTable = purchaseContractDetailDOList.stream()
                .filter(o -> Objects.nonNull(o.getPurchaseItemCode()) && Objects.nonNull(o.getContractCode()))
                .collect(Tables.toTable(
                        PurchaseContractDetailDO::getContractCode,
                        PurchaseContractDetailDO::getPurchaseItemCode,
                        Function.identity(),
                        (v1, v2) -> v1,
                        HashBasedTable::create
                ));


        Table<String, String, OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOTable = purchaseOrderManager.getPurchaseOrderDetailBOTable(poCodeList);
        // Map<合同编号,合同信息>
        List<PurchaseReceiptDO> purchaseReceiptDOList = purchaseReceiptDAO.getByPoCodes(poCodeList);
        // Map<poCode,验收入库单>
        Map<String, List<PurchaseReceiptDO>> purchaseReceiptListMap = new HashMap<>();
        // Map<poCode,历史验收明细>
        Map<String, List<PurchaseReceiptDetailDO>> poCodeToHistoryReceiptDetailMap = new HashMap<>();
        if (CollectionUtils.isNotEmpty(purchaseReceiptDOList)) {
            purchaseReceiptDOList = purchaseReceiptDOList.stream().filter(item -> SupplierDataStatusEnums.SUBMIT.getCode().equals(item.getAuditStatus()) || SupplierDataStatusEnums.PASS.getCode().equals(item.getAuditStatus())).collect(Collectors.toList());
            purchaseReceiptListMap = purchaseReceiptDOList.stream().collect(Collectors.groupingBy(PurchaseReceiptDO::getPoCode));
            List<String> riCodes = purchaseReceiptDOList.stream().map(PurchaseReceiptDO::getPurchaseReceiptCode).distinct().collect(Collectors.toList());
            List<PurchaseReceiptDetailDO> purchaseReceiptDetailDOSList = purchaseReceiptDetailDAO.getByRiCodes(riCodes);
            Map<String, List<PurchaseReceiptDetailDO>> purchaseReceiptDetailDOSListMap = purchaseReceiptDetailDOSList.stream().collect(Collectors.groupingBy(PurchaseReceiptDetailDO::getPurchaseReceiptCode));
            purchaseReceiptListMap.forEach((po, receipts) -> {
                List<String> riCodeList = receipts.stream().map(PurchaseReceiptDO::getPurchaseReceiptCode).distinct().collect(Collectors.toList());
                List<PurchaseReceiptDetailDO> nestedDetailList = riCodeList.stream()
                        .map(purchaseReceiptDetailDOSListMap::get)
                        .filter(CollectionUtils::isNotEmpty)
                        .flatMap(List::stream)
                        .collect(Collectors.toList());
                poCodeToHistoryReceiptDetailMap.put(po, nestedDetailList);
            });
        }
        // Map<PoCode,付款单信息>
        Map<String, List<PurchasePaymentRequestDO>> poPurchasePaymentRequestMap = purchasePaymentRequestDAO.getByPoCodes(poCodeList).stream()
                .collect(Collectors.groupingBy(PurchasePaymentRequestDO::getPoCode));

        List<PurchaseOrderItemDetailExportVO> exportList = new ArrayList<>();
        for (PurchaseOrderPageVO orderPageVO : poList) {
            String poCode = orderPageVO.getPoCode();
            // 单据明细信息
            List<PurchaseOrderDetailDO> poDetailList = purchaseOrderDetailMap.get(poCode);
            if (ObjectUtil.isEmpty(poDetailList)) {
                PurchaseOrderItemDetailExportVO purchaseOrderItemDetailExportVO = new PurchaseOrderItemDetailExportVO(orderPageVO);
                exportList.add(purchaseOrderItemDetailExportVO);
                continue;
            }
            for (PurchaseOrderDetailDO pod : poDetailList) {
                PurchaseOrderItemDetailExportVO purchaseOrderItemDetailExportVO = new PurchaseOrderItemDetailExportVO(orderPageVO);
                String purchaseItemCode = pod.getPurchaseItemCode();
                PurchaseItemCodeDO itemCode = itemCodeMap.get(purchaseItemCode);
                // 单位unit 物料/服务描述itemName 属性描述typeDesc 采购编码purchaseItemCode
                purchaseOrderItemDetailExportVO.setUnit(itemCode.getUnit());
                purchaseOrderItemDetailExportVO.setItemName(itemCode.getItemName());
                purchaseOrderItemDetailExportVO.setType(itemCode.getType());
                purchaseOrderItemDetailExportVO.setPurchaseItemCode(itemCode.getItemCode());
                // 采购金额purchaseAmount 采购含税金额taxInclusiveAmount 需求到货日期requiredDeliveryDate 采购备注purchaseRemarks 采购数量purchaseQty
                purchaseOrderItemDetailExportVO.setTaxInclusiveAmount(pod.getTaxInclusiveAmount());
                purchaseOrderItemDetailExportVO.setRequiredDeliveryDate(pod.getRequiredDeliveryDate());
                purchaseOrderItemDetailExportVO.setPurchaseRemarks(pod.getPurchaseRemarks());
                purchaseOrderItemDetailExportVO.setPurchaseAmount(pod.getPurchaseAmount());
                purchaseOrderItemDetailExportVO.setPurchaseQty(pod.getPurchaseQty());
                // 单价、含税单价
                OrderBO.PurchaseOrderDetailBO purchaseOrderDetailBO = purchaseOrderDetailBOTable.get(poCode, purchaseItemCode);
                BigDecimal purchaseQty = purchaseOrderDetailBO.getPurchaseOrderDetailDO().getPurchaseQty();
                BigDecimal taxInclusiveAmount = purchaseOrderDetailBO.getPurchaseOrderDetailDO().getTaxInclusiveAmount();
                OrderItemBO orderItemBO;
                if (AuditStatusEnum.getUnSubmitList().contains(SafeEnumUtil.getBy(AuditStatusEnum::getCode, orderPageVO.getAuditStatus()))) {
                    Map<String, List<PurchaseContractDetailPriceSettingDO>> contractDetailPriceMap
                            = contractCodeItemCodePriceMap.getOrDefault(orderPageVO.getAssociatedContract(), new HashMap<>());
                    List<PurchaseContractDetailPriceSettingDO> itemCodePriceSettingList = contractDetailPriceMap.getOrDefault(pod.getPurchaseItemCode(), new ArrayList<>());
                    PurchaseContractDetailDO purchaseContractDetailDO = purchaseContractDetailDOTable.get(orderPageVO.getAssociatedContract(), purchaseItemCode);
                    orderItemBO = handleItemAmount(orderPageVO.getItemInputMode(), taxInclusiveAmount, purchaseQty, purchaseContractDetailDO, itemCodePriceSettingList);
                } else {
                    orderItemBO = handleItemAmount(orderPageVO.getItemInputMode(), purchaseOrderDetailBO);
                }
                purchaseOrderItemDetailExportVO.setSettlementCurrency(orderPageVO.getSettlementCurrency());
                purchaseOrderItemDetailExportVO.setTaxRate( DecimalUtils.scale(DecimalUtils.multiply(orderItemBO.getItemCodeTaxRate(), new BigDecimal("100")),2));
                String itemCodePrice = orderItemBO.toPriceExcludingTax();
                String itemCodeTaxInclusivePrice = orderItemBO.toPriceIncludingTax();
                // 不含税单价price
                purchaseOrderItemDetailExportVO.setPrice(itemCodePrice);
                // 含税单价taxInclusiveAmount
                purchaseOrderItemDetailExportVO.setTaxInclusivePrice(itemCodeTaxInclusivePrice);
                // 累计验收数量、累计验收金额、累计验收含税金额（拿累计数量对比阶梯价计算）
                List<PurchaseReceiptDetailDO> historyReceiptDetailList = poCodeToHistoryReceiptDetailMap.getOrDefault(poCode, Collections.emptyList());
                List<PurchaseReceiptDO> receiptListByPo = purchaseReceiptListMap.get(poCode);
                if (CollectionUtils.isNotEmpty(historyReceiptDetailList)) {
                    Map<String, OrderItemBO> historyOrderItemMap = this.getReceiptPriceMap(orderPageVO.getItemInputMode(),
                            new ArrayList<>(purchaseOrderDetailBOTable.row(poCode).values()),
                            historyReceiptDetailList);
                    OrderItemBO cumulativeReceiptItem = historyOrderItemMap.get(purchaseItemCode);
                    if (Objects.nonNull(cumulativeReceiptItem)) {
                        purchaseOrderItemDetailExportVO.setCumulativeReceiptQty(cumulativeReceiptItem.getQty());
                        purchaseOrderItemDetailExportVO.setCumulativeReceiptAmount(DecimalUtils.scale(cumulativeReceiptItem.getAmountExcludingTax()));
                        purchaseOrderItemDetailExportVO.setCumulativeTaxInclusiveReceiptAmount(DecimalUtils.scale(cumulativeReceiptItem.getAmountIncludingTax()));
                        if (CollectionUtils.isNotEmpty(receiptListByPo)) {
                            List<PurchaseReceiptDO> purchaseReceiptList = receiptListByPo.stream().sorted(Comparator.comparing(PurchaseReceiptDO::getCreateDate).reversed()).collect(Collectors.toList());
                            purchaseOrderItemDetailExportVO.setActualDeliveryDate(purchaseReceiptList.get(0).getCreateDate());
                        }
                    }
                }
                if (poPurchasePaymentRequestMap.containsKey(poCode)) {
                    purchaseOrderItemDetailExportVO.setPurchasePaymentRequestCodeStr(
                            poPurchasePaymentRequestMap.get(poCode).stream()
                                    .map(PurchasePaymentRequestDO::getPurchasePaymentRequestCode)
                                    .collect(Collectors.joining(StrUtil.COMMA))
                    );
                }
                if (ObjectUtil.isNotEmpty(purchaseOrderItemDetailExportVO.getAssociatedRiList())) {
                    purchaseOrderItemDetailExportVO.setAssociatedRiListStr(
                            purchaseOrderItemDetailExportVO.getAssociatedRiList().stream()
                                    .map(AssociatedPurchaseReceiptVO::getPurchaseReceiptCode)
                                    .collect(Collectors.joining(StrUtil.COMMA))
                    );
                }
                exportList.add(purchaseOrderItemDetailExportVO);
            }
        }

        if (exportList != null) {
            converterService.withAnnotation(exportList);
            exportList.forEach(poPageVO -> {

                List<AssociatedPurchaseReceiptVO> associatedRiList = poPageVO.getAssociatedRiList();
                if (associatedRiList != null) {
                    converterService.withAnnotation(associatedRiList);
                }
            });
        }
        return PaginationResult.get(exportList, page.getPagination());
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void antiApproval(String poCode) {
        log.info("antiApproval | poCode={}", poCode);
        if (StringUtils.isBlank(poCode)) {
            return;
        }
        PurchaseOrderDO oldOrder = purchaseOrderDAO.getByPoCode(poCode);
        if (Objects.isNull(oldOrder)) {
            return;
        }
        log.info("antiApproval | oldOrder={}", oldOrder);
        if (!Objects.equals(AuditStatusEnum.PASS, AuditStatusEnum.getInstance(oldOrder.getAuditStatus()))) {
            throw BusinessException.get(ErrorCodeEnums.AUDIT_STATUS_ERROR.getCode(),
                    I18nUtils.getMessage(ErrorCodeEnums.AUDIT_STATUS_ERROR.getDesc(), poCode));
        }

        List<PurchaseReceiptDO> receiptList = purchaseReceiptDAO.getByPoCode(poCode);
        List<PurchasePaymentRequestDO> paymentRequestList = purchasePaymentRequestDAO.getByPoCode(poCode);
        log.info("antiApproval ｜ poCode={} ｜ receiptList={} ｜ paymentRequestList={}",
                poCode, receiptList, paymentRequestList);

        // 校验是否有关联审批中或审批通过的单据
        List<String> receiptCodeList = receiptList.stream()
                .filter(Objects::nonNull)
                .filter(order -> AuditStatusEnum.getApprovalList().contains(AuditStatusEnum.getInstance(order.getAuditStatus())))
                .map(PurchaseReceiptDO::getPurchaseReceiptCode)
                .collect(Collectors.toList());
        List<String> paymentRequestCodeList = paymentRequestList.stream()
                .filter(Objects::nonNull)
                .filter(order -> AuditStatusEnum.getApprovalList().contains(AuditStatusEnum.getInstance(order.getAuditStatus())))
                .map(PurchasePaymentRequestDO::getPurchasePaymentRequestCode)
                .collect(Collectors.toList());
        log.info("antiApproval ｜ receiptCodeList={} | paymentRequestCodeList={}", receiptCodeList, paymentRequestCodeList);
        if (CollectionUtils.isNotEmpty(receiptCodeList) || CollectionUtils.isNotEmpty(paymentRequestCodeList)) {
            String codeListStr = Lists.newArrayList(receiptCodeList, paymentRequestCodeList).stream()
                    .filter(CollectionUtils::isNotEmpty)
                    .flatMap(Collection::stream)
                    .collect(Collectors.joining(StrUtil.COMMA));
            throw BusinessException.get(ErrorCodeEnums.ANTI_APPROVAL_ERROR.getCode(),
                    I18nUtils.getMessage(ErrorCodeEnums.ANTI_APPROVAL_ERROR.getDesc(), "PO", poCode, "RI/PY", codeListStr));
        }


        // 删除关联下游未提交或审批不通过的单据
        List<PurchaseReceiptDO> deleteRiList = receiptList.stream()
                .map(ri -> {
                    PurchaseReceiptDO deleteRi = new PurchaseReceiptDO();
                    deleteRi.setId(ri.getId());
                    deleteRi.setIsDelete(IsDeleteEnum.YES.getValue());
                    BaseDOUtil.updateDO(deleteRi);
                    return deleteRi;
                }).collect(Collectors.toList());
        log.info("antiApproval ｜ deleteRiList={} ", deleteRiList);
        purchaseReceiptDAO.updateBatchById(deleteRiList);

        List<PurchasePaymentRequestDO> deletePyList = paymentRequestList.stream()
                .map(py -> {
                    PurchasePaymentRequestDO deletePy = new PurchasePaymentRequestDO();
                    deletePy.setId(py.getId());
                    deletePy.setIsDelete(IsDeleteEnum.YES.getValue());
                    BaseDOUtil.updateDO(deletePy);
                    return deletePy;
                }).collect(Collectors.toList());
        log.info("antiApproval ｜ deletePyList={} ", deletePyList);
        purchasePaymentRequestDAO.updateBatchById(deletePyList);

        paymentRequestList.stream()
                .map(PurchasePaymentRequestDO::getPurchasePaymentRequestCode)
                .forEach(pyCode -> EasyLogUtil.record(pyCode, ModuleCode.PAYMENT,OperateType.DELETE, LogContentTemplate.REVERT,new String[]{poCode}));

        //  单据状态改为未提交
        PurchaseOrderDO updateOrder = new PurchaseOrderDO();
        updateOrder.setId(oldOrder.getId());
        updateOrder.setAuditStatus(AuditStatusEnum.NOT_SUBMIT.getCode());
        updateOrder.setCompleteStatus(IsDeleteEnum.NO.getValue());
        BaseDOUtil.updateDO(updateOrder);
        log.info("antiApproval ｜ updateOrder={} ", updateOrder);
        purchaseOrderDAO.updateById(updateOrder);

        // 删除审批数据
        List<PurchaseOrderAuditDO> poAuditList = purchaseOrderAuditDAO.getByPoCode(poCode);
        List<PurchaseOrderAuditDO> deleteOrderAuditList = poAuditList.stream()
                .map(poAudit -> {
                    PurchaseOrderAuditDO deleteOrderAudit = new PurchaseOrderAuditDO();
                    deleteOrderAudit.setId(poAudit.getId());
                    deleteOrderAudit.setIsDelete(IsDeleteEnum.YES.getValue());
                    BaseDOUtil.updateDO(deleteOrderAudit);
                    return deleteOrderAudit;
                }).collect(Collectors.toList());
        log.info("antiApproval ｜ deleteOrderAuditList={} ", deleteOrderAuditList);
        purchaseOrderAuditDAO.updateBatchById(deleteOrderAuditList);
        //重算PR完结状态
        recalculatePrCompletionStatus(oldOrder.getPrCode());

        PurchaseOrderCreateApiDTO purchaseOrderCreateApiDTO = getPurchaseOrderCreateApiDTO(oldOrder);
        if (Objects.nonNull(purchaseOrderCreateApiDTO)) {
            thirdAccessPlatformIntegration.createPOReverseApprovalInfo(poCode,oldOrder.getPrCode());
        }
    }

    @Override
    public Boolean isDownPaymentAndOneHundred(String contractCode) {
        List<PurchaseContractRedemptionPeriodDO> contractRedemptionPeriodDOS = purchaseContractRedemptionPeriodDAO.getByContractCode(contractCode);
        if (CollectionUtils.isNotEmpty(contractRedemptionPeriodDOS)) {
            return contractRedemptionPeriodDOS.stream().anyMatch(contractRedemptionPeriodDO ->
                    StringUtils.equals(contractRedemptionPeriodDO.getPaymentMethod(), PaymentMethodEnums.DOWN_PAYMENT.getCode()) &&
                            contractRedemptionPeriodDO.getPaymentRatio().compareTo(BigDecimal.ONE) == 0);
        }
        return false;
    }


    /**
     * 校验是否可修改：单据审核中、单号和解密后的单号一致，可修改单据
     *
     * @param purchaseOrderDO
     * @param encodePoCode
     */
    private void checkUpdatePermission(PurchaseOrderDO purchaseOrderDO, String encodePoCode) {
        //单据是否审核中
        if (!SupplierDataStatusEnums.SUBMIT.getCode().equals(purchaseOrderDO.getAuditStatus())) {
            throw BusinessException.get(ErrorCodeEnums.NOT_UNDER_REVIEW.getCode(), I18nUtils.getMessage(ErrorCodeEnums.NOT_UNDER_REVIEW.getDesc()));
        }

        //单号和解密后的单号是否一致
        String decode = Base64.decodeToString(encodePoCode);
        if (!purchaseOrderDO.getPoCode().equals(decode)) {
            throw BusinessException.get(ErrorCodeEnums.NOT_ALLOWED_TO_UPDATE_APPROVAL.getCode(), I18nUtils.getMessage(ErrorCodeEnums.NOT_ALLOWED_TO_UPDATE_APPROVAL.getDesc()));
        }

    }

    /**
     * PO主表信息复制
     *
     * @param oldPurchaseOrderDO
     * @param purchaseRequisitionDO
     * @param purchaseContractInfoDO
     */
    private void buildNewPo(String newPoCode, PurchaseOrderDO oldPurchaseOrderDO, PurchaseRequisitionDO purchaseRequisitionDO, PurchaseContractInfoDO purchaseContractInfoDO) {
        PurchaseOrderDO newPurchaseOrderDO = new PurchaseOrderDO();

        newPurchaseOrderDO.setId(IdWorkerUtil.getId());
        newPurchaseOrderDO.setPoCode(newPoCode);
        newPurchaseOrderDO.setAuditStatus(SupplierDataStatusEnums.SAVE.getCode());
        newPurchaseOrderDO.setPrCode(oldPurchaseOrderDO.getPrCode());
        newPurchaseOrderDO.setContractCode(oldPurchaseOrderDO.getContractCode());
        newPurchaseOrderDO.setPurchaseDate(LocalDateTime.now());
        newPurchaseOrderDO.setDeliveryAddress(purchaseRequisitionDO.getDeliveryPoint());
        if (purchaseContractInfoDO != null) {
            newPurchaseOrderDO.setShippingAddress(purchaseContractInfoDO.getShipFromAddress());
        }
        newPurchaseOrderDO.setBuyerCode(purchaseRequisitionDO.getBuyerCode());
        newPurchaseOrderDO.setRemarks(oldPurchaseOrderDO.getRemarks());
        newPurchaseOrderDO.setOneDeptId(oldPurchaseOrderDO.getOneDeptId());
        newPurchaseOrderDO.setTwoDeptId(oldPurchaseOrderDO.getTwoDeptId());
        newPurchaseOrderDO.setPurchaseOrganizationAddress(oldPurchaseOrderDO.getPurchaseOrganizationAddress());
        if (Objects.nonNull(purchaseContractInfoDO)){
            newPurchaseOrderDO.setSiteNumber(purchaseContractInfoDO.getSiteNumber());
        }else {
            newPurchaseOrderDO.setSiteNumber(oldPurchaseOrderDO.getSiteNumber());
        }
        BaseDOUtil.insertDO(newPurchaseOrderDO);
        purchaseOrderDAO.save(newPurchaseOrderDO);
    }

    /**
     * 单个PO详情V2
     *
     * @param poCode
     * @return
     */
    @Override
    public PurchaseOrderVO getOneByPoCode(String poCode) {
        boolean isChinese = Locale.CHINA.equals(UserEvnHolder.getLocal());

        PurchaseOrderVO purchaseOrderVO = new PurchaseOrderVO();
        //1、PO基本信息
        //查询PO表
        PurchaseOrderBasicInfoDTO purchaseOrderBasicInfo = purchaseOrderMapper.getBasicInfo(poCode);
        if (purchaseOrderBasicInfo == null) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getDesc()));
        }
        BeanUtils.copyProperties(purchaseOrderBasicInfo, purchaseOrderVO);
        purchaseOrderVO.setDownPaymentWriteOffDate(DateTimeUtils.nullIfEqualToDefault(purchaseOrderBasicInfo.getDownPaymentWriteOffDate()));

        //（1）PR带出
        //采购品类
        String categorySubtypeCode = purchaseOrderBasicInfo.getCategorySubtypeCode();
        purchaseOrderVO.setCategorySubtypeCode(categorySubtypeCode);
        SupplierCategoryDO supplierCategoryDO = supplierCategoryDAO.getByCategorySubtypeCode(categorySubtypeCode);
        if (supplierCategoryDO != null) {
            if (isChinese) {
                purchaseOrderVO.setCategorySubtypeName(supplierCategoryDO.getCategorySubtypeNameChn());
            } else {
                purchaseOrderVO.setCategorySubtypeName(supplierCategoryDO.getCategorySubtypeNameEn());
            }
        }

        //一二级部门
        Long oneDeptId = purchaseOrderBasicInfo.getOneDeptId();
        Long twoDeptId = purchaseOrderBasicInfo.getTwoDeptId();
        if (oneDeptId != null) {
            OrgDeptApiDTO oneDeptInfo = hrmsOrgIntegration.getDeptInfo(oneDeptId);
            if (oneDeptInfo != null) {
                if (isChinese) {
                    purchaseOrderVO.setOneDeptName(oneDeptInfo.getDeptNameCn());
                } else {
                    purchaseOrderVO.setOneDeptName(oneDeptInfo.getDeptNameEn());
                }
            }
            //二级部门
            if (twoDeptId != null) {
                OrgDeptApiDTO twoDeptInfo = hrmsOrgIntegration.getDeptInfo(twoDeptId);
                if (twoDeptInfo != null) {
                    if (isChinese) {
                        purchaseOrderVO.setTwoDeptName(twoDeptInfo.getDeptNameCn());
                    } else {
                        purchaseOrderVO.setTwoDeptName(twoDeptInfo.getDeptNameEn());
                    }
                }
            }
        }
        //采购员
        Map<String, String> userNameMap = hrmsApi.getUserNameMap(Collections.singletonList(purchaseOrderBasicInfo.getBuyerCode()));
        purchaseOrderVO.setBuyerName(userNameMap.get(purchaseOrderBasicInfo.getBuyerCode()));
        OrderBO orderBO = purchaseOrderManager.getOrderBO(poCode);
        PurchaseOrderDO purchaseOrderDO = orderBO.getPurchaseOrderDO();
        //（2）合同带出
        String contractCode = purchaseOrderDO.getContractCode();
        if (StringUtils.isNotBlank(contractCode)) {
            PurchaseContractInfoDO purchaseContractInfoDO = purchaseContractInfoDAO.getByContractCode(contractCode);
            //采购组织\供应商名称\供应商邮箱\币种
            if (purchaseContractInfoDO.getContractOrgId() != null) {
                OrgSettlementCenterDTO purchaseOrgDTO = hrmsOrgIntegration.getSettlementById(purchaseContractInfoDO.getContractOrgId());
                purchaseOrderVO.setPurchaseOrgName(purchaseOrgDTO == null ? null : purchaseOrgDTO.getSettlementCenterName());
                purchaseOrderVO.setPurchaseOrgId(purchaseContractInfoDO.getContractOrgId());
            }
            SupplierInfoRes supplierInfoRes = sdsIntegration.getByCode(purchaseContractInfoDO.getSupplierCode());
            purchaseOrderVO.setSupplierShortName(supplierInfoRes.getSupplierName());
            purchaseOrderVO.setSupplierCode(supplierInfoRes.getSupplierCode());
            purchaseOrderVO.setSupplierAddress(supplierInfoRes.getContactAddress());
            List<SupplierContactRes> contactList = sdsIntegration.getContactListByCode(purchaseContractInfoDO.getSupplierCode());
            Map<Integer, SupplierContactRes> contactMap = contactList.stream().collect(Collectors.toMap(SupplierContactRes::getJobTitleCode, Function.identity(), (v1, v2) -> v1));
            SupplierContactRes supplierContactRes = contactMap.get(JobTitleEnum.COMMERCIAL.getCode());
            if (Objects.nonNull(supplierContactRes)) {
                purchaseOrderVO.setSupplierEmail(supplierContactRes.getEmail());
            }
            List<SupplierFinancialBankRes> financialBankList = sdsIntegration.getFinancialBankListByCode(purchaseContractInfoDO.getSupplierCode());
            Map<Integer, SupplierFinancialBankRes> financialBankMap = financialBankList.stream().collect(Collectors.toMap(SupplierFinancialBankRes::getSiteNumber, Function.identity(), (v1, v2) -> v1));

            Integer siteNumber = AuditStatusEnum.getUnSubmitList().contains(SafeEnumUtil.getBy(AuditStatusEnum::getCode, purchaseOrderDO.getAuditStatus()))
                    ? purchaseContractInfoDO.getSiteNumber()
                    : purchaseOrderDO.getSiteNumber();
            SupplierFinancialBankRes supplierFinancialBankRes = financialBankMap.get(siteNumber);
            if (Objects.nonNull(supplierFinancialBankRes)) {
                purchaseOrderVO.setSettlementCurrency(supplierFinancialBankRes.getSettlementCurrency());
            }
            //付款条件
            String paymentTerm = purchaseContractRedemptionPeriodDAO.getPaymentTermByContractCode(contractCode);
            purchaseOrderVO.setPaymentTerm(paymentTerm);

            //PO采购编码
            List<PurchaseOrderDetailDO> purchaseOrderDetailDOS = purchaseOrderDetailDAO.getByPoCode(poCode);
            if (CollectionUtils.isNotEmpty(purchaseOrderDetailDOS)) {
                //封装Map<采购编码,采购编码表信息>
                List<String> itemCodes = purchaseOrderDetailDOS.stream().map(PurchaseOrderDetailDO::getPurchaseItemCode).collect(Collectors.toList());
                HashMap<String, PurchaseItemCodeDO> itemCodeMap = purchaseItemCodeDAO.getItemCodeMap(itemCodes);
                //采购价格
                List<OrderItemBO> purchasePriceOrderItemBOList =  this.getPurchasePrice(orderBO);
                Map<String, OrderItemBO> purchasePriceOrderItemBOMap = purchasePriceOrderItemBOList.stream().collect(Collectors.toMap(OrderItemBO::getPurchaseItemCode, Function.identity(), (v1, v2) -> v1));
                //验收价格
                List<OrderItemBO> receiptPriceOrderItemBOList = this.getReceiptPrice(orderBO);
                Map<String, OrderItemBO> receiptPriceOrderItemBOMap = receiptPriceOrderItemBOList.stream().collect(Collectors.toMap(OrderItemBO::getPurchaseItemCode, Function.identity(), (v1, v2) -> v1));
                //PO采购编码数据封装
                List<PurchaseOrderDetailVO> poDetailVOS = new ArrayList<>();
                for (PurchaseOrderDetailDO purchaseOrderDetailDO : purchaseOrderDetailDOS) {
                    PurchaseOrderDetailVO purchaseOrderDetailVO = new PurchaseOrderDetailVO();
                    //描述、属性、单位
                    String purchaseItemCode = purchaseOrderDetailDO.getPurchaseItemCode();
                    PurchaseItemCodeDO purchaseItemCodeDO = itemCodeMap.get(purchaseItemCode);
                    purchaseOrderDetailVO.setProductCode(purchaseItemCodeDO.getProductCode());
                    BeanUtils.copyProperties(purchaseItemCodeDO, purchaseOrderDetailVO);
                    //采购数量、采购金额、采购含税金额、要求交付日期、备注
                    BeanUtils.copyProperties(purchaseOrderDetailDO, purchaseOrderDetailVO);
                    //币种、税率
                    purchaseOrderDetailVO.setSettlementCurrency(purchaseOrderVO.getSettlementCurrency());
                    //单价、含税单价
                    OrderItemBO purchasePriceOrderItemBO = purchasePriceOrderItemBOMap.get(purchaseOrderDetailDO.getPurchaseItemCode());
                    if (Objects.nonNull(purchasePriceOrderItemBO)) {
                        purchaseOrderDetailVO.setChargingMethod(purchasePriceOrderItemBO.getChargingMethod());
                        purchaseOrderDetailVO.setPriceMatchMode(purchasePriceOrderItemBO.getPriceMatchMode());
                        purchaseOrderDetailVO.setPrice(purchasePriceOrderItemBO.toPriceExcludingTax());
                        purchaseOrderDetailVO.setTaxInclusivePrice(purchasePriceOrderItemBO.toPriceIncludingTax());
                        purchaseOrderDetailVO.setPurchaseAmount(purchasePriceOrderItemBO.getAmountExcludingTax());
                        purchaseOrderDetailVO.setTaxInclusiveAmount(purchasePriceOrderItemBO.getAmountIncludingTax());
                        purchaseOrderDetailVO.setTaxRate(DecimalUtils.scale(DecimalUtils.multiply(purchasePriceOrderItemBO.getItemCodeTaxRate(), new BigDecimal("100")), 2));
                        purchaseOrderDetailVO.setPurchaseQty(purchasePriceOrderItemBO.getQty());
                    }
                    //累计验收数量、累计验收金额、累计验收含税金额（拿累计数量对比阶梯价计算）
                    OrderItemBO receiptPriceOrderItemBO = receiptPriceOrderItemBOMap.get(purchaseItemCode);
                    if (Objects.nonNull(receiptPriceOrderItemBO)) {
                        purchaseOrderDetailVO.setCumulativeReceiptQty(receiptPriceOrderItemBO.getQty());
                        purchaseOrderDetailVO.setCumulativeReceiptAmount(receiptPriceOrderItemBO.getAmountExcludingTax());
                        purchaseOrderDetailVO.setCumulativeTaxInclusiveReceiptAmount(receiptPriceOrderItemBO.getAmountIncludingTax());
                        List<PurchaseReceiptDO> purchaseReceiptDOS = purchaseReceiptDAO.getByPoCode(purchaseOrderDO.getPoCode());
                        LocalDateTime actualDeliveryDate = purchaseReceiptDOS.stream().map(PurchaseReceiptDO::getCreateDate).max(Comparator.comparing(Function.identity())).orElse(null);
                        purchaseOrderDetailVO.setActualDeliveryDate(actualDeliveryDate);
                    }
                    //如果是阶梯价，返回阶梯价范围，以供前端动态展示
                    List<LadderPriceSettingVO> ladderPriceSettingVOList = new ArrayList<>();
                    if (ChargingMethodEnums.getLadderPriceList().contains(SafeEnumUtil.getBy(ChargingMethodEnums::getCode, purchasePriceOrderItemBO.getChargingMethod()))) {
                        List<OrderItemBO.OrderPriceBO> orderPriceBOList = purchasePriceOrderItemBO.getOrderPriceBOList();
                        ladderPriceSettingVOList = orderPriceBOList.stream()
                                .map(orderPriceBO -> {
                                    LadderPriceSettingVO ladderPriceSettingVO = new LadderPriceSettingVO();
                                    ladderPriceSettingVO.setMinQty(orderPriceBO.getMinQty());
                                    ladderPriceSettingVO.setMaxQty(orderPriceBO.getMaxQty());
                                    ladderPriceSettingVO.setPrice(scale(orderPriceBO.getPriceExcludingTax()));
                                    ladderPriceSettingVO.setTaxInclusivePrice(scale(orderPriceBO.getPriceIncludingTax()));
                                    return ladderPriceSettingVO;
                                })
                                .collect(Collectors.toList());
                    }
                    purchaseOrderDetailVO.setLadderPriceSettingList(ladderPriceSettingVOList);
                    poDetailVOS.add(purchaseOrderDetailVO);
                }
                purchaseOrderVO.setPoDetailList(poDetailVOS);
            }
        }

        //PO费用分摊
        List<PurchaseOrderBudgetAllocationDO> budgetAllocationDOS = orderBO.getPurchaseOrderBudgetAllocationDOList();
        List<BudgetAllocationInfoVO> budgetAllocationInfoList = hrmsApiService.getBudgetAllocationInfo(BudgetAllocationInfoParam.getByPo(budgetAllocationDOS));
        Map<Integer, Map<String, BudgetAllocationInfoVO>> budgetAllocationInfoMap = hrmsApiService.toBudgetAllocationInfoMap(budgetAllocationInfoList);
        List<PurchaseOrderBudgetAllocationVO> poBudgetAllocationVOS = new ArrayList<>();
        for (PurchaseOrderBudgetAllocationDO budgetAllocationDO : budgetAllocationDOS) {
            PurchaseOrderBudgetAllocationVO poBudgetAllocationVO = new PurchaseOrderBudgetAllocationVO();
            BeanUtils.copyProperties(budgetAllocationDO, poBudgetAllocationVO);
            poBudgetAllocationVO.setFeeBearingPercentage(DecimalUtils.stripTrailingZeros(DecimalUtils.scale(DecimalUtils.multiply(budgetAllocationDO.getFeeBearingPercentage(), new BigDecimal("100")), 2)));
            poBudgetAllocationVO.setFeeBearingAmount(DecimalUtils.stripTrailingZeros(DecimalUtils.scale(budgetAllocationDO.getFeeBearingAmount())));
            //部门、网点、费用项目名称
            Function<BudgetAllocationInfoVO, String> function = isChinese ? (BudgetAllocationInfoVO::getNameCn) : (BudgetAllocationInfoVO::getNameEn);
            poBudgetAllocationVO.setDeptName(hrmsApiService.getName(budgetAllocationInfoMap, BudgetAllocationTypeEnum.DEPT.getValue(), Objects.toString(poBudgetAllocationVO.getDeptId()), function));
            poBudgetAllocationVO.setStationName(hrmsApiService.getName(budgetAllocationInfoMap, BudgetAllocationTypeEnum.STATION.getValue(), Objects.toString(poBudgetAllocationVO.getStationCode()), function));
            poBudgetAllocationVO.setFeeBearingItemName(hrmsApiService.getName(budgetAllocationInfoMap, BudgetAllocationTypeEnum.FEE_BEARING_ITEM.getValue(), Objects.toString(poBudgetAllocationVO.getFeeBearingItemCode()), function));
            poBudgetAllocationVO.setFeeTypeDesc(hrmsApiService.getName(budgetAllocationInfoMap, BudgetAllocationTypeEnum.FEE_TYPE.getValue(), Objects.toString(budgetAllocationDO.getFeeType()), function));
            poBudgetAllocationVOS.add(poBudgetAllocationVO);
        }
        purchaseOrderVO.setPoBudgetAllocationList(poBudgetAllocationVOS);

        //PO附件
        List<PmsFileInfoDO> fileInfoDOS = pmsFileInfoDAO.getFileInfos(poCode, FileInfoTypeEnums.PO_FILE.getType());
        List<PmsFileInfoVO> pmsFileInfoVOS = new ArrayList<>();
        for (PmsFileInfoDO fileInfoDO : fileInfoDOS) {
            PmsFileInfoVO pmsFileInfoVO = new PmsFileInfoVO();
            BeanUtils.copyProperties(fileInfoDO, pmsFileInfoVO);
            pmsFileInfoVOS.add(pmsFileInfoVO);
        }
        purchaseOrderVO.setPoFileList(pmsFileInfoVOS);

        //审批流Code
        PurchaseOrderAuditDO purchaseOrderAuditDO = purchaseOrderAuditDAO.getLastByPoCode(poCode);
        if (purchaseOrderAuditDO != null) {
            purchaseOrderVO.setAuditCode(purchaseOrderAuditDO.getAuditCode());
        }

        if (StringUtils.isEmpty(contractCode)) {
            purchaseOrderVO.setIsDisplayDownPaymentWriteOffDate(false);
        } else {
            purchaseOrderVO.setIsDisplayDownPaymentWriteOffDate(isDownPaymentAndOneHundred(contractCode));
        }

        return purchaseOrderVO;
    }

    private OrderItemBO calculateItemAmount(PriceScenario scenario, PriceCalculationContext context) {
        PriceCalculator calculator = priceCalculatorMap.get(scenario);
        if (Objects.isNull(calculator)) {
            throw new IllegalStateException("价格计算器未注册，场景:" + scenario);
        }
        return calculator.calculate(context);
    }

    @Override
    public List<OrderItemBO> handleItemAmount(String itemInputMode, List<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOList) {
        return emptyIfNull(purchaseOrderDetailBOList)
                .stream()
                .filter(Objects::nonNull)
                .map(detailBO -> calculateItemAmount(PriceScenario.ORDER, PriceCalculationContext.builder()
                        .itemInputMode(itemInputMode)
                        .orderDetailBO(detailBO)
                        .build()))
                .collect(Collectors.toList());
    }

    @Override
    public OrderItemBO handleItemAmount(OrderBO.PurchaseOrderDetailBO purchaseOrderDetailBO) {
        if (Objects.isNull(purchaseOrderDetailBO) || Objects.isNull(purchaseOrderDetailBO.getPurchaseOrderDetailDO())) {
            return new OrderItemBO();
        }
        String poCode = purchaseOrderDetailBO.getPurchaseOrderDetailDO().getPoCode();
        PurchaseOrderDO purchaseOrderDO = purchaseOrderDAO.getByPoCode(poCode);
        if (Objects.isNull(purchaseOrderDO)) {
            return new OrderItemBO();
        }
        return calculateItemAmount(PriceScenario.ORDER, PriceCalculationContext.builder()
                .itemInputMode(purchaseOrderDO.getItemInputMode())
                .orderDetailBO(purchaseOrderDetailBO)
                .build());
    }

    @Override
    public OrderItemBO handleItemAmount(String itemInputMode, OrderBO.PurchaseOrderDetailBO purchaseOrderDetailBO) {
        if (Objects.isNull(purchaseOrderDetailBO)) {
            return new OrderItemBO();
        }
        return calculateItemAmount(PriceScenario.ORDER, PriceCalculationContext.builder()
                .itemInputMode(itemInputMode)
                .orderDetailBO(purchaseOrderDetailBO)
                .build());
    }


    @Override
    public List<OrderItemBO> handleItemAmount(String itemInputMode, Map<String, BigDecimal> qtyMap, List<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOList) {
        Map<String, BigDecimal> finalQtyMap = Optional.ofNullable(qtyMap).orElse(Collections.emptyMap());
        return emptyIfNull(purchaseOrderDetailBOList)
                .stream()
                .filter(Objects::nonNull)
                .map(purchaseOrderDetailBO -> {
                    String purchaseItemCode = Optional.ofNullable(purchaseOrderDetailBO)
                            .map(OrderBO.PurchaseOrderDetailBO::getPurchaseOrderDetailDO)
                            .map(PurchaseOrderDetailDO::getPurchaseItemCode).
                            orElse(StringUtils.EMPTY);
                    BigDecimal qty = finalQtyMap.get(purchaseItemCode);
                    return calculateItemAmount(PriceScenario.ORDER, PriceCalculationContext.builder()
                            .itemInputMode(itemInputMode)
                            .inputQty(qty)
                            .orderDetailBO(purchaseOrderDetailBO)
                            .build());
                }).collect(Collectors.toList());
    }

    @Override
    public List<OrderItemBO> handleItemAmount(String itemInputMode,List<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOList, List<PurchaseContractDetailDO> purchaseContractDetailDOList, List<PurchaseContractDetailPriceSettingDO> purchaseContractDetailPriceSettingDOList) {
        Map<String, PurchaseOrderDetailDO> purchaseOrderDetailDOMap = emptyIfNull(purchaseOrderDetailBOList).stream()
                .filter(Objects::nonNull)
                .map(OrderBO.PurchaseOrderDetailBO::getPurchaseOrderDetailDO)
                .filter(Objects::nonNull)
                .filter(o -> Objects.nonNull(o.getPurchaseItemCode()) )
                .collect(Collectors.toMap(PurchaseOrderDetailDO::getPurchaseItemCode,Function.identity(),
                        (v1, v2) -> v1));

        Map<String, List<PurchaseContractDetailPriceSettingDO>> contractDetailPriceSettingDOMap = emptyIfNull(purchaseContractDetailPriceSettingDOList).stream()
                .filter(s -> StringUtils.isNotBlank(s.getItemCode()))
                .collect(Collectors.groupingBy(PurchaseContractDetailPriceSettingDO::getItemCode));

        return emptyIfNull(purchaseContractDetailDOList)
                .stream()
                .filter(Objects::nonNull)
                .map(purchaseContractDetailDO -> {
                    String purchaseItemCode = purchaseContractDetailDO.getPurchaseItemCode();
                    List<PurchaseContractDetailPriceSettingDO> settings = contractDetailPriceSettingDOMap.get(purchaseItemCode);
                    PurchaseOrderDetailDO purchaseOrderDetailDO = purchaseOrderDetailDOMap.get(purchaseItemCode);
                    BigDecimal qty = null;
                    BigDecimal taxInclusiveAmount = null;
                    if (Objects.nonNull(purchaseOrderDetailDO)) {
                        qty = purchaseOrderDetailDO.getPurchaseQty();
                        taxInclusiveAmount = purchaseOrderDetailDO.getTaxInclusiveAmount();
                    }
                    return calculateItemAmount(PriceScenario.CONTRACT, PriceCalculationContext.builder()
                            .itemInputMode(itemInputMode)
                            .inputQty(qty)
                            .inputAmount(taxInclusiveAmount)
                            .contractDetailDO(purchaseContractDetailDO)
                            .contractPriceSettingList(settings)
                            .build());
                }).collect(Collectors.toList());
    }

    @Override
    public OrderItemBO handleItemAmount(String itemInputMode,BigDecimal taxInclusiveAmount,BigDecimal qty, PurchaseContractDetailDO purchaseContractDetailDO, List<PurchaseContractDetailPriceSettingDO> purchaseContractDetailPriceSettingDOList) {
        if (Objects.isNull(purchaseContractDetailDO)) {
           return new OrderItemBO();
        }
        return calculateItemAmount(PriceScenario.CONTRACT, PriceCalculationContext.builder()
                .itemInputMode(itemInputMode)
                .inputQty(qty)
                .inputAmount(taxInclusiveAmount)
                .contractDetailDO(purchaseContractDetailDO)
                .contractPriceSettingList(purchaseContractDetailPriceSettingDOList)
                .build());
    }


    @Override
    public OrderItemBO calculateAmount(OrderItemDTO dto) {
        if (StringUtils.isBlank(dto.getItemInputMode())) {
            dto.setItemInputMode(ItemInputModeEnums.QUANTITY.getCode());
        }
        OrderItemBO orderItemBO = purchaseOrderManager.handleItemCodePurchaseAmount(dto);
        orderItemBO.setQty(DecimalUtils.scale(orderItemBO.getQty()));
        orderItemBO.setItemCodeTaxRate(DecimalUtils.scale(orderItemBO.getItemCodeTaxRate()));
        orderItemBO.setAmountExcludingTax(DecimalUtils.scale(orderItemBO.getAmountExcludingTax()));
        orderItemBO.setAmountIncludingTax(DecimalUtils.scale(orderItemBO.getAmountIncludingTax()));
        if (CollectionUtils.isNotEmpty(orderItemBO.getOrderPriceBOList())) {
            orderItemBO.getOrderPriceBOList().forEach(
                    o -> {
                        o.setPriceExcludingTax(DecimalUtils.scale(o.getPriceExcludingTax()));
                        o.setPriceIncludingTax(DecimalUtils.scale(o.getPriceIncludingTax()));
                        o.setMinQty(DecimalUtils.scale(o.getMinQty()));
                        o.setMaxQty(DecimalUtils.scale(o.getMaxQty()));
                    }
            );
        }
        return orderItemBO;
    }

    private List<OrderItemBO> getReceiptPrice(OrderBO orderBO) {
        PurchaseOrderDO purchaseOrderDO = orderBO.getPurchaseOrderDO();
        List<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOList = orderBO.getPurchaseOrderDetailBOList();

        ReceiptAggregationContext aggregationContext = aggregateReceiptHistory(purchaseOrderDO.getPoCode());
