    @Override
    public ReceiptAggregationContext aggregateReceiptHistory(String poCode) {
        List<PurchaseReceiptDO> purchaseReceiptDOS = purchaseReceiptDAO.getByPoCode(poCode);
        if (CollectionUtils.isEmpty(purchaseReceiptDOS)) {
            return emptyReceiptAggregationContext();
        }
        List<PurchaseReceiptDO> effectiveReceiptDOS = purchaseReceiptDOS.stream()
                .filter(item -> Objects.equals(item.getAuditStatus(), SupplierDataStatusEnums.SUBMIT.getCode())
                        || Objects.equals(item.getAuditStatus(), SupplierDataStatusEnums.PASS.getCode()))
                .collect(Collectors.toList());
        if (CollectionUtils.isEmpty(effectiveReceiptDOS)) {
            return emptyReceiptAggregationContext();
        }
        List<String> riCodes = effectiveReceiptDOS.stream()
                .map(PurchaseReceiptDO::getPurchaseReceiptCode)
                .filter(StringUtils::isNotBlank)
                .distinct()
                .collect(Collectors.toList());
        if (CollectionUtils.isEmpty(riCodes)) {
            return emptyReceiptAggregationContext();
        }
        List<PurchaseReceiptDetailDO> detailDOS = purchaseReceiptDetailDAO.getByRiCodes(riCodes);
        return aggregateReceiptDetails(detailDOS);
    }

    private ReceiptAggregationContext aggregateReceiptDetails(List<PurchaseReceiptDetailDO> receiptDetailDOList) {
        if (CollectionUtils.isEmpty(receiptDetailDOList)) {
            return emptyReceiptAggregationContext();
        }
        Map<String, BigDecimal> qtyMap = Optional.ofNullable(purchaseReceiptDetailDAO.getCumulativeReceiptQtyMap(receiptDetailDOList))
                .orElse(new HashMap<>());
        Map<String, BigDecimal> amountMap = receiptDetailDOList.stream()
                .filter(detail -> Objects.nonNull(detail) && StringUtils.isNotBlank(detail.getPurchaseItemCode()))
                .collect(Collectors.groupingBy(PurchaseReceiptDetailDO::getPurchaseItemCode,
                        Collectors.reducing(BigDecimal.ZERO,
                                detail -> Objects.nonNull(detail.getTaxInclusiveReceiptAmount()) ? detail.getTaxInclusiveReceiptAmount() : BigDecimal.ZERO,
                                BigDecimal::add)));
        return ReceiptAggregationContext.builder()
                .cumulativeReceiptQtyMap(qtyMap)
                .cumulativeReceiptAmountMap(amountMap)
                .receiptDetailList(receiptDetailDOList)
                .build();
    }

    private ReceiptAggregationContext emptyReceiptAggregationContext() {
        return ReceiptAggregationContext.builder()
                .cumulativeReceiptQtyMap(Collections.emptyMap())
                .cumulativeReceiptAmountMap(Collections.emptyMap())
                .receiptDetailList(Collections.emptyList())
                .build();
    }

    private List<OrderItemBO> getReceiptPrice(String itemInputMode,
                                              List<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOList,
                                              ReceiptAggregationContext aggregationContext) {
        if (Objects.isNull(aggregationContext) || CollectionUtils.isEmpty(aggregationContext.getReceiptDetailList())) {
            return new ArrayList<>();
        }
        Map<String, BigDecimal> qtyMap = Optional.ofNullable(aggregationContext.getCumulativeReceiptQtyMap()).orElse(Collections.emptyMap());
        Map<String, BigDecimal> amountMap = Optional.ofNullable(aggregationContext.getCumulativeReceiptAmountMap()).orElse(Collections.emptyMap());
        return handleItemReceiptAmount(itemInputMode, qtyMap, amountMap, purchaseOrderDetailBOList);
    }

    @Override
    public Map<String, OrderItemBO> getReceiptPriceMap(String itemInputMode,
                                             List<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOList,
                                             List<PurchaseReceiptDetailDO> purchaseReceiptDetailDOList) {
        ReceiptAggregationContext aggregationContext = aggregateReceiptDetails(purchaseReceiptDetailDOList);
        List<OrderItemBO> orderItemBOList = getReceiptPrice(itemInputMode, purchaseOrderDetailBOList, aggregationContext);

        Map<String, OrderItemBO> result = orderItemBOList.stream()
                .filter(Objects::nonNull)
                .filter(orderItemBO -> StringUtils.isNotBlank(orderItemBO.getPurchaseItemCode()))
                .collect(Collectors.toMap(OrderItemBO::getPurchaseItemCode, Function.identity(), (v1, v2) -> v2));
        if (CollectionUtils.isEmpty(purchaseReceiptDetailDOList)) {
            // 若不存在历史验收记录，默认返回零值，避免调用方空指针
            emptyIfNull(purchaseOrderDetailBOList)
                    .stream()
                    .map(OrderBO.PurchaseOrderDetailBO::getPurchaseOrderDetailDO)
                    .filter(Objects::nonNull)
                    .map(PurchaseOrderDetailDO::getPurchaseItemCode)
                    .filter(StringUtils::isNotBlank)
                    .forEach(itemCode -> result.computeIfAbsent(itemCode, code -> {
                        OrderItemBO zero = new OrderItemBO();
                        zero.setPurchaseItemCode(code);
                        zero.setQty(DecimalUtils.ZERO);
                        zero.setAmountExcludingTax(DecimalUtils.ZERO);
                        zero.setAmountIncludingTax(DecimalUtils.ZERO);
                        return zero;
                    }));
        }
        return result;
    }

    @Override
    public ReceiptPriceSummary getReceiptPriceSummary(String itemInputMode,
                                                      List<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOList,
                                                      List<PurchaseReceiptDetailDO> historyReceiptDetailDOList,
                                                      List<PurchaseReceiptDetailDO> currentReceiptDetailDOList) {

        List<PurchaseReceiptDetailDO> safeCurrentList = new ArrayList<>(emptyIfNull(currentReceiptDetailDOList));
        // 将当前验收的采购单号+采购编码组合从历史中剔除，避免重复累计
        Set<String> currentKeys = safeCurrentList.stream()
                .filter(Objects::nonNull)
                .filter(detail -> StringUtils.isNotBlank(detail.getPurchaseReceiptCode()) && StringUtils.isNotBlank(detail.getPurchaseItemCode()))
                .map(detail -> detail.getPurchaseReceiptCode() + PmsStringUtil.HASH_MARK + detail.getPurchaseItemCode())
                .collect(Collectors.toSet());
        List<PurchaseReceiptDetailDO> safeHistoryList = emptyIfNull(historyReceiptDetailDOList).stream()
                .filter(Objects::nonNull)
                .filter(detail -> {
                    if (StringUtils.isBlank(detail.getPurchaseReceiptCode()) || StringUtils.isBlank(detail.getPurchaseItemCode())) {
                        return true;
                    }
                    String key = detail.getPurchaseReceiptCode() + PmsStringUtil.HASH_MARK + detail.getPurchaseItemCode();
                    return !currentKeys.contains(key);
                })
                .collect(Collectors.toList());
        ReceiptAggregationContext historyContext = aggregateReceiptDetails(safeHistoryList);
        Map<String, OrderItemBO> historyMap = getReceiptPrice(itemInputMode, purchaseOrderDetailBOList, historyContext)
                .stream()
                .filter(Objects::nonNull)
                .filter(orderItemBO -> StringUtils.isNotBlank(orderItemBO.getPurchaseItemCode()))
                .collect(Collectors.toMap(OrderItemBO::getPurchaseItemCode, Function.identity(), (v1, v2) -> v2));

        // 历史 + 本次
        List<PurchaseReceiptDetailDO> mergedList = Stream.concat(safeCurrentList.stream(), safeHistoryList.stream())
                .collect(Collectors.toList());
        ReceiptAggregationContext mergedContext = aggregateReceiptDetails(mergedList);
        Map<String, OrderItemBO> mergedMap = getReceiptPrice(itemInputMode, purchaseOrderDetailBOList, mergedContext)
                .stream()
                .filter(Objects::nonNull)
                .filter(orderItemBO -> StringUtils.isNotBlank(orderItemBO.getPurchaseItemCode()))
                .collect(Collectors.toMap(OrderItemBO::getPurchaseItemCode, Function.identity(), (v1, v2) -> v2));

        // 本次 = (历史+本次) - 历史
        Map<String, OrderItemBO> deltaMap = new HashMap<>();
        Set<String> itemCodes = emptyIfNull(purchaseOrderDetailBOList).stream()
                .map(OrderBO.PurchaseOrderDetailBO::getPurchaseOrderDetailDO)
                .filter(Objects::nonNull)
                .map(PurchaseOrderDetailDO::getPurchaseItemCode)
                .filter(StringUtils::isNotBlank)
                .collect(Collectors.toSet());
        itemCodes.addAll(historyMap.keySet());
        itemCodes.addAll(mergedMap.keySet());
        itemCodes.forEach(code -> {
            OrderItemBO merged = mergedMap.get(code);
            OrderItemBO history = historyMap.get(code);
            BigDecimal mergedQty = Optional.ofNullable(merged).map(OrderItemBO::getQty).orElse(DecimalUtils.ZERO);
            BigDecimal historyQty = Optional.ofNullable(history).map(OrderItemBO::getQty).orElse(DecimalUtils.ZERO);
            BigDecimal mergedAmount = Optional.ofNullable(merged).map(OrderItemBO::getAmountExcludingTax).orElse(DecimalUtils.ZERO);
            BigDecimal historyAmount = Optional.ofNullable(history).map(OrderItemBO::getAmountExcludingTax).orElse(DecimalUtils.ZERO);
            BigDecimal mergedTaxAmount = Optional.ofNullable(merged).map(OrderItemBO::getAmountIncludingTax).orElse(DecimalUtils.ZERO);
            BigDecimal historyTaxAmount = Optional.ofNullable(history).map(OrderItemBO::getAmountIncludingTax).orElse(DecimalUtils.ZERO);

            OrderItemBO delta = new OrderItemBO();
            delta.setPurchaseItemCode(code);
            delta.setQty(DecimalUtils.subtract(mergedQty, historyQty));
            delta.setAmountExcludingTax(DecimalUtils.subtract(mergedAmount, historyAmount));
            delta.setAmountIncludingTax(DecimalUtils.subtract(mergedTaxAmount, historyTaxAmount));
            deltaMap.put(code, delta);
        });

        // 补零，确保所有编码存在键，调用方使用时不必判空
        itemCodes.forEach(code -> historyMap.computeIfAbsent(code, c -> {
            OrderItemBO zero = new OrderItemBO();
            zero.setPurchaseItemCode(c);
            zero.setQty(DecimalUtils.ZERO);
            zero.setAmountExcludingTax(DecimalUtils.ZERO);
            zero.setAmountIncludingTax(DecimalUtils.ZERO);
            return zero;
        }));
        itemCodes.forEach(code -> deltaMap.computeIfAbsent(code, c -> {
            OrderItemBO zero = new OrderItemBO();
            zero.setPurchaseItemCode(c);
            zero.setQty(DecimalUtils.ZERO);
            zero.setAmountExcludingTax(DecimalUtils.ZERO);
            zero.setAmountIncludingTax(DecimalUtils.ZERO);
            return zero;
        }));

        return ReceiptPriceSummary.builder()
                .history(historyMap)
                .current(deltaMap)
                .historyPlusCurrent(mergedMap)
                .build();
    }

