    public List<OrderItemBO> handleItemReceiptAmount(String itemInputMode, Map<String, BigDecimal> qtyMap, Map<String, BigDecimal> amountMap, List<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOList) {
        Map<String, BigDecimal> finalQtyMap = Optional.ofNullable(qtyMap).orElse(Collections.emptyMap());
        Map<String, BigDecimal> finalAmountMap = Optional.ofNullable(amountMap).orElse(Collections.emptyMap());
        return emptyIfNull(purchaseOrderDetailBOList)
                .stream()
                .filter(Objects::nonNull)
                .map(purchaseOrderDetailBO -> {
                    String purchaseItemCode = Optional.ofNullable(purchaseOrderDetailBO)
                            .map(OrderBO.PurchaseOrderDetailBO::getPurchaseOrderDetailDO)
                            .map(PurchaseOrderDetailDO::getPurchaseItemCode).
                            orElse(StringUtils.EMPTY);
                    BigDecimal qty = finalQtyMap.get(purchaseItemCode);
                    BigDecimal amount = finalAmountMap.get(purchaseItemCode);
                    return calculateItemAmount(PriceScenario.RECEIPT, PriceCalculationContext.builder()
                            .itemInputMode(itemInputMode)
                            .orderDetailBO(purchaseOrderDetailBO)
                            .cumulativeReceiptQty(qty)
                            .cumulativeReceiptAmount(amount)
                            .build());
                }).collect(Collectors.toList());
    }




    private List<OrderItemBO> getPurchasePrice(OrderBO orderBO) {
        PurchaseOrderDO purchaseOrderDO = orderBO.getPurchaseOrderDO();
        String contractCode = purchaseOrderDO.getContractCode();
        List<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOList = orderBO.getPurchaseOrderDetailBOList();
        //如果是审批中、审批通过，使用订单价格
        if (AuditStatusEnum.getApprovalList().contains(SafeEnumUtil.getBy(AuditStatusEnum::getCode, purchaseOrderDO.getAuditStatus()))) {
            return handleItemAmount(purchaseOrderDO.getItemInputMode(),purchaseOrderDetailBOList);
        } else {
            //如果是未提交、审批不通过，使用合同价格
            List<PurchaseContractDetailPriceSettingDO> contractDetailPriceMap = purchaseContractDetailPriceSettingDAO.getByContractCode(contractCode);
            List<PurchaseContractDetailDO> contractDetailList = purchaseContractDetailDAO.getDetailByContractCode(contractCode);
            return handleItemAmount(purchaseOrderDO.getItemInputMode(),purchaseOrderDetailBOList, contractDetailList, contractDetailPriceMap);
        }
    }

    /**
     * 批量删除PO
     *
     * @param poCodeList
     * @return
     */
    @Override
    @Transactional
    public List<DeleteFailVO> deletePo(List<String> poCodeList) {
        if (CollectionUtils.isEmpty(poCodeList)) {
            throw BusinessException.get(ErrorCodeEnums.DATA_NOT_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.DATA_NOT_EXIST.getDesc()));
        }

        //判断PO是否存在
        List<PurchaseOrderDO> purchaseOrderDOS = purchaseOrderDAO.getByPoCodes(poCodeList);
        if (CollectionUtils.isEmpty(purchaseOrderDOS) || purchaseOrderDOS.size() != poCodeList.size()) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getDesc()));
        }
        //判断是否可删除：审核状态为未提交状态或审核不通过才可删除
        List<PurchaseOrderDO> cannotDelList = purchaseOrderDOS.stream().filter(DO -> SupplierDataStatusEnums.SUBMIT.getCode().equals(DO.getAuditStatus()) || SupplierDataStatusEnums.PASS.getCode().equals(DO.getAuditStatus()))
                .collect(Collectors.toList());
        if (CollectionUtils.isNotEmpty(cannotDelList)) {
            List<DeleteFailVO> deleteFailVOS = new ArrayList<>();
            Locale local = UserEvnHolder.getLocal();
            for (PurchaseOrderDO orderDO : cannotDelList) {
                DeleteFailVO deleteFailVO = new DeleteFailVO();
                deleteFailVO.setDocumentCode(orderDO.getPoCode());
                if (Locale.CHINA.equals(local)) {
                    deleteFailVO.setDeleteFailReason(ErrorCodeEnums.PURCHASE_REQUISITION_CANNOT_DELETE.getMessage());
                } else {
                    deleteFailVO.setDeleteFailReason(ErrorCodeEnums.PURCHASE_REQUISITION_CANNOT_DELETE.getDesc());
                }
                deleteFailVOS.add(deleteFailVO);
            }
            return deleteFailVOS;
        }

        //逻辑删除 PO表
        for (PurchaseOrderDO purchaseOrderDO : purchaseOrderDOS) {
            purchaseOrderDO.setIsDelete(CommonConstant.Y);
            BaseDOUtil.updateDO(purchaseOrderDO);
        }
        purchaseOrderDAO.updateBatchById(purchaseOrderDOS);
        //逻辑删除 PO的Detail表
        purchaseOrderDetailDAO.deleteHistoryByPoCodes(poCodeList);
        //逻辑删除 文件表
        List<PmsFileInfoDO> pmsFileInfoDOS = pmsFileInfoDAO.listFileInfos(poCodeList, FileInfoTypeEnums.PO_FILE.getType());
        for (PmsFileInfoDO pmsFileInfoDO : pmsFileInfoDOS) {
            pmsFileInfoDO.setIsDelete(CommonConstant.Y);
            BaseDOUtil.updateDO(pmsFileInfoDO);
        }
        pmsFileInfoDAO.updateBatchById(pmsFileInfoDOS);

        return null;
    }

