    /**
     * 查看关联验收单号
     *
     * @param poCode
     * @return
     */
    @Override
    @Transactional
    public List<AssociatedPurchaseReceiptVO> getAssociatedRi(String poCode, String riCode) {
        OrderBO orderBO = purchaseOrderManager.getOrderBO(poCode);
        PurchaseAssert.isEmpty(orderBO,ErrorCodeEnums.NOT_EXIST,poCode);

        PurchaseOrderDO purchaseOrderDO = orderBO.getPurchaseOrderDO();
        List<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOList = orderBO.getPurchaseOrderDetailBOList();

        //PO关联合同号
        String contractCode = purchaseOrderDO.getContractCode();
        if (StringUtils.isBlank(contractCode)) {
            return new ArrayList<>();
        }

        //查询PO关联的RI（如果是RI列表或详情内的关联验收单号，需要剔除RI本身；如果是PO详情内的关联RI单号，展示所有RI）
        List<PurchaseReceiptDO> purchaseReceiptDOS = purchaseReceiptDAO.getByPoCode(poCode);
        if (CollectionUtils.isEmpty(purchaseReceiptDOS)) {
            return new ArrayList<>();
        }
        if (StringUtils.isNotBlank(riCode)) {
            purchaseReceiptDOS = purchaseReceiptDOS.stream().filter(item -> !riCode.equals(item.getPurchaseReceiptCode())).collect(Collectors.toList());
        }
        //封装Map<RI号，采购编码集合>
        List<String> riCodes = purchaseReceiptDOS.stream().map(PurchaseReceiptDO::getPurchaseReceiptCode).distinct().collect(Collectors.toList());
        List<PurchaseReceiptDetailDO> purchaseReceiptDetailDOS = purchaseReceiptDetailDAO.getByRiCodes(riCodes);
        Map<String, List<PurchaseReceiptDetailDO>> riMap = purchaseReceiptDetailDOS.stream()
                .collect(Collectors.groupingBy(PurchaseReceiptDetailDO::getPurchaseReceiptCode));
        //供应商简称
        PurchaseContractInfoDO purchaseContractInfoDO = purchaseContractInfoDAO.getByContractCode(contractCode);
        String supplierCode = purchaseContractInfoDO.getSupplierCode();
        SupplierInfoRes supplierInfoRes = sdsIntegration.getByCode(supplierCode);
        String supplierShortName = supplierInfoRes.getSupplierShortName();

        Map<String, OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOMap = purchaseOrderDetailBOList.stream()
                .collect(Collectors.toMap(o -> o.getPurchaseOrderDetailDO().getPurchaseItemCode(), Function.identity(), (v1, v2) -> v1));

        //返回值封装
        List<AssociatedPurchaseReceiptVO> associatedPurchaseReceiptVOS = new ArrayList<>();
        for (PurchaseReceiptDO purchaseReceiptDO : purchaseReceiptDOS) {
            AssociatedPurchaseReceiptVO associatedPurchaseReceiptVO = new AssociatedPurchaseReceiptVO();
            BeanUtils.copyProperties(purchaseReceiptDO, associatedPurchaseReceiptVO);
            //供应商简称
            associatedPurchaseReceiptVO.setSupplierShortName(supplierShortName);
            //验收数量\验收金额\验收含税金额
            ArrayList<OrderItemBO> orderItemBOList = new ArrayList<>();

            List<PurchaseReceiptDetailDO> receiptDetailDOS = riMap.get(purchaseReceiptDO.getPurchaseReceiptCode());
            for (PurchaseReceiptDetailDO receiptDetailDO : receiptDetailDOS) {
                OrderBO.PurchaseOrderDetailBO purchaseOrderDetailBO = purchaseOrderDetailBOMap.get(receiptDetailDO.getPurchaseItemCode());
                if (Objects.nonNull(purchaseOrderDetailBO)) {
                    PurchaseOrderDetailDO purchaseOrderDetailDO = purchaseOrderDetailBO.getPurchaseOrderDetailDO();
                    List<OrderDetailPriceSettingDO> orderDetailPriceSettingDOList = purchaseOrderDetailBO.getOrderDetailPriceSettingDOList();
                    OrderItemDTO orderItemDTO = OrderStructMapper.INSTANCE.toOrderItemDTO(purchaseOrderDetailDO, orderDetailPriceSettingDOList);
                    orderItemDTO.setQty(receiptDetailDO.getReceiptQty());
                    OrderItemBO orderItemBO = purchaseOrderManager.handleItemCodePurchaseAmount(orderItemDTO);
                    orderItemBOList.add(orderItemBO);
                }
            }
            associatedPurchaseReceiptVO.setTotalReceiptQty(receiptDetailDOS.stream().map(PurchaseReceiptDetailDO::getReceiptQty).reduce(DecimalUtils::add).orElse(new BigDecimal("0")));
            BigDecimal totalReceiptAmount = orderItemBOList.stream().map(OrderItemBO::getAmountExcludingTax).reduce(DecimalUtils::add).orElse(new BigDecimal("0"));
            BigDecimal totalTaxInclusiveReceiptAmount = orderItemBOList.stream().map(OrderItemBO::getAmountIncludingTax).reduce(DecimalUtils::add).orElse(new BigDecimal("0"));
            associatedPurchaseReceiptVO.setTotalReceiptAmount(DecimalUtils.stripTrailingZeros(DecimalUtils.scale(totalReceiptAmount)));
            associatedPurchaseReceiptVO.setTotalTaxInclusiveReceiptAmount(DecimalUtils.stripTrailingZeros(DecimalUtils.scale(totalTaxInclusiveReceiptAmount)));
            associatedPurchaseReceiptVOS.add(associatedPurchaseReceiptVO);
        }

        return associatedPurchaseReceiptVOS;
    }

    /**
     * 查看关联付款申请单号
     *
     * @param poCode
     * @return
     */
    @Override
    @Transactional
    public List<AssociatedPaymentRequestVO> getAssociatedPy(String poCode) {
        PurchaseOrderDO purchaseOrderDO = purchaseOrderDAO.getByPoCode(poCode);
        if (purchaseOrderDO == null) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getDesc()));
        }
        //PO关联合同号
        String contractCode = purchaseOrderDO.getContractCode();
        if (StringUtils.isBlank(contractCode)) {//还未关联合同时，无关联付款单
            return new ArrayList<>();
        }

        //查询PO关联PY
        List<PurchasePaymentRequestDO> paymentRequestDOS = purchasePaymentRequestDAO.getByPoCode(poCode);
        List<String> supplierCodeList = paymentRequestDOS.stream().map(PurchasePaymentRequestDO::getSupplierCode).distinct().collect(Collectors.toList());
        List<SupplierInfoRes> supplierInfoResList = sdsIntegration.getByCodeList(supplierCodeList);
        Map<String, String> supplierShortNameMap = supplierInfoResList.stream().collect(Collectors.toMap(SupplierInfoRes::getSupplierCode, SupplierInfoRes::getSupplierShortName, (v1, v2) -> v1));
        //返回值封装
        List<AssociatedPaymentRequestVO> associatedPaymentRequestVOS = new ArrayList<>();
        for (PurchasePaymentRequestDO paymentRequestDO : paymentRequestDOS) {
            AssociatedPaymentRequestVO associatedPaymentRequestVO = new AssociatedPaymentRequestVO();
            BeanUtils.copyProperties(paymentRequestDO, associatedPaymentRequestVO);
            associatedPaymentRequestVO.setRequiredPayment(paymentRequestDO.getRequiredPayment().setScale(4, BigDecimal.ROUND_HALF_UP));
            associatedPaymentRequestVO.setSettledAmount(paymentRequestDO.getSettledAmount().setScale(4, BigDecimal.ROUND_HALF_UP));
            //供应商简称
            associatedPaymentRequestVO.setSupplierShortName(supplierShortNameMap.get(paymentRequestDO.getSupplierCode()));
            //全部支付：已付款金额=申请金额
            if (SettleStatusEnums.SETTLED.getCode().equals(paymentRequestDO.getSettleStatus())) {
                associatedPaymentRequestVO.setSettledAmount(paymentRequestDO.getRequiredPayment().setScale(4, BigDecimal.ROUND_HALF_UP));
            }
            associatedPaymentRequestVOS.add(associatedPaymentRequestVO);
        }

        return associatedPaymentRequestVOS;
    }

    /**
     * 审核通过后的处理
     *
     * @param poCode
     */
    @Override
    @Transactional
    public void pass(String poCode,String createSource) {
        log.info("PO pass: " + poCode);
        String userCode = UcenterUtils.getUserInfo().getUserCode();
        UserDTO user = hrmsIntegration.getUserByUserCode(userCode);
        LocalDateTime now = LocalDateTime.now();
        //1、修改PO表的审核状态
        PurchaseOrderDO purchaseOrderDO = purchaseOrderDAO.getByPoCode(poCode);
        if (purchaseOrderDO == null) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getDesc()));
        }
        purchaseOrderDO.setAuditStatus(SupplierDataStatusEnums.PASS.getCode());
        purchaseOrderDO.setApprovalInfoStatus(ApprovalInfoStatusEnums.PASS.getCode());
        purchaseOrderDO.setAuditDate(now);
        purchaseOrderDO.setAuditUserCode(userCode);
        purchaseOrderDO.setAuditUserName(user.getUnifiedUserName());
        BaseDOUtil.updateDO(purchaseOrderDO);
        purchaseOrderDAO.updateById(purchaseOrderDO);

        //2、修改PO审核表最新审核记录
        PurchaseOrderAuditDO purchaseOrderAuditDO = purchaseOrderAuditDAO.getLastByPoCode(poCode);
        purchaseOrderAuditDO.setAuditStatus(SupplierDataStatusEnums.PASS.getCode());
        purchaseOrderAuditDO.setAuditDate(now);
        purchaseOrderAuditDO.setAuditUserCode(userCode);
        purchaseOrderAuditDO.setAuditUserName(user.getUserName());
        BaseDOUtil.updateDO(purchaseOrderAuditDO);
        purchaseOrderAuditDAO.updateById(purchaseOrderAuditDO);

        try {
            //3、PR自动完结：比较关联PR的预算金额 和 PR底下所有审核通过的PO的采购含税金额之和(含本单)
            recalculatePrCompletionStatus(purchaseOrderDO.getPrCode());
        } catch (Exception e) {
            log.error("PR auto complete fail: " + purchaseOrderDO.getPrCode() + " " + e);
        }

        String prCode = purchaseOrderDO.getPrCode();
        PurchaseRequisitionDO purchaseRequisitionDO = purchaseRequisitionDAO.getByPrCode(prCode);
        //该PR底下所有审核通过的PO的采购含税金额之和

        //4、合同有预付条款\PO底下无关联预付款单——生成预付款单
        try {
            autoCreatePrepaidPy(poCode, purchaseRequisitionDO,createSource);
        } catch (Exception e) {
            log.error("PO auto create prepaid payment fail: " + poCode + " " + e);
        }

        //5、发送邮件给供应商商务联系人和pr需求人,pr提交人邮箱
        try {
            sendEmail(purchaseOrderDO, purchaseRequisitionDO);
        } catch (Exception e) {
            log.error("PO send mail fail " + poCode + " " + e);
        }

        //6.生成一个未提交的RI单
        try {
            String riCode = purchaseReceiptManagerService.createRiWithPassPO(purchaseOrderDO,createSource);
            log.info("PO auto create RICode: " + riCode);
        } catch (Exception e) {
            log.error("PO auto create RI fail,poCode={}", poCode, e);
        }
        //订单同步到资产系统
        try {
            syncOrderTo(purchaseOrderDO);
        } catch (Exception e) {
            log.error("同步订单到资产系统失败:" + poCode, e);
        }
    }


    @Value("#{'${asset.category.code.list:CS0001,CS0002,CS0047,CS0011,CS0012,CS0013,CS0049}'.split(',')}")
    private List<String> assetCategorySubtypeCodeList;

    public PurchaseOrderCreateApiDTO getPurchaseOrderCreateApiDTO(PurchaseOrderDO purchaseOrderDO) {
        PurchaseContractInfoDO contract = purchaseContractInfoDAO.getByContractCode(purchaseOrderDO.getContractCode());
        if (!assetCategorySubtypeCodeList.contains(contract.getCategorySubtypeCode())) {
            return null;
        }

        List<PurchaseOrderDetailDO> orderDetailList = purchaseOrderDetailDAO.getByPoCode(purchaseOrderDO.getPoCode());
        List<String> itemCodeList = orderDetailList.stream()
                .map(PurchaseOrderDetailDO::getPurchaseItemCode)
                .collect(Collectors.toList());
        List<PurchaseItemCodeDO> itemList = purchaseItemCodeDAO.getListByItemCodes(itemCodeList);
        List<PurchaseItemCodeTypeEnums> amsTypeList = getAmsTypeList();
        itemList = itemList.stream()
                .filter(item -> amsTypeList.contains(PurchaseItemCodeTypeEnums.getInstance(item.getType())))
                .filter(item -> assetCategorySubtypeCodeList.contains(item.getCategorySubtypeCode()))
                .collect(Collectors.toList());
        if (CollectionUtils.isEmpty(itemList)) {
            return null;
        }
        Map<String, PurchaseItemCodeDO> itemMap = itemList.stream()
                .collect(Collectors.toMap(PurchaseItemCodeDO::getItemCode, Function.identity(), (v1, v2) -> v1));
        List<PurchaseContractDetailPriceSettingDO> contractDetailPriceList = purchaseContractDetailPriceSettingDAO.getByContractCode(purchaseOrderDO.getContractCode());
        Map<String, PurchaseContractDetailPriceSettingDO> contractDetailPriceMap = contractDetailPriceList.stream()
                .collect(Collectors.toMap(PurchaseContractDetailPriceSettingDO::getItemCode, Function.identity(), (v1, v2) -> v1));

        PurchaseOrderCreateApiDTO purchaseOrderCreateApiDTO = new PurchaseOrderCreateApiDTO();
        purchaseOrderCreateApiDTO.setShippingAddress(purchaseOrderDO.getDeliveryAddress());
        purchaseOrderCreateApiDTO.setPurchaseOrderNo(purchaseOrderDO.getPoCode());
        purchaseOrderCreateApiDTO.setPrCode(purchaseOrderDO.getPrCode());
        purchaseOrderCreateApiDTO.setCompanyCode(String.valueOf(contract.getContractOrgId()));
        purchaseOrderCreateApiDTO.setOrderTime(System.currentTimeMillis());
        purchaseOrderCreateApiDTO.setSupplierCode(contract.getSupplierCode());
        purchaseOrderCreateApiDTO.setComment(purchaseOrderDO.getRemarks());
        purchaseOrderCreateApiDTO.setStatus(2);

        List<PurchaseOrderCreateApiDTO.PurchaseOrderDetail> detailList = orderDetailList.stream()
                .filter(o -> DecimalUtils.greaterThan(o.getPurchaseQty(), BigDecimal.ZERO))
                .map(detail -> {
                    PurchaseOrderCreateApiDTO.PurchaseOrderDetail purchaseOrderDetail = new PurchaseOrderCreateApiDTO.PurchaseOrderDetail();
                    PurchaseItemCodeDO item = itemMap.get(detail.getPurchaseItemCode());
                    if (Objects.isNull(item)) {
                        return null;
                    }
                    PurchaseContractDetailPriceSettingDO purchaseContractDetailPriceSetting = contractDetailPriceMap.get(detail.getPurchaseItemCode());
                    if (Objects.isNull(purchaseContractDetailPriceSetting)) {
                        return null;
                    }

                    purchaseOrderDetail.setSkuCode(detail.getPurchaseItemCode());
                    BigDecimal taxPrice = DecimalUtils.multiply(purchaseContractDetailPriceSetting.getPrice(), add(detail.getItemCodeTaxRate(), BigDecimal.ONE));
                    BigDecimal taxPriceUsd = commonService.getUsdAmount(contract.getSettlementCurrency(), taxPrice);
                    purchaseOrderDetail.setSkuType(DecimalUtils.lessThan(taxPriceUsd, new BigDecimal("300")) ? 2 : 1);

                    purchaseOrderDetail.setAssetTemplateName(item.getItemName());
                    purchaseOrderDetail.setAssetTypeCode(item.getCategorySubtypeCode());
                    purchaseOrderDetail.setDisplayIndex(orderDetailList.indexOf(detail) + 1);
                    BigDecimal purchaseQty = DecimalUtils.scale(detail.getPurchaseQty(), 0, 4);
                    if (Objects.nonNull(purchaseQty)) {
                        purchaseOrderDetail.setQuantity(purchaseQty.intValue());
                    }
                    OriginAmountDto originAmountDto = new OriginAmountDto();
                    originAmountDto.setOriginCurrency(contract.getSettlementCurrency());
                    originAmountDto.setAmount(detail.getTaxInclusiveAmount());
                    originAmountDto.setExchangeRateTime(new Date());
                    originAmountDto.setCompanyId(String.valueOf(contract.getContractOrgId()));
                    ExchangeRateAmountDto exchangeRateAmountDto = accountingCenter.queryExchangeRateAmount(originAmountDto);

                    purchaseOrderDetail.setAmount(DecimalUtils.toPlainString(exchangeRateAmountDto.getTransferAmount()));
                    purchaseOrderDetail.setTaxRate(DecimalUtils.toPlainString(DecimalUtils.multiple(detail.getItemCodeTaxRate(), 100)));

                    OriginAmountDto amountDto = new OriginAmountDto();
                    amountDto.setOriginCurrency(contract.getSettlementCurrency());
                    amountDto.setAmount(detail.getPurchaseAmount());
                    amountDto.setExchangeRateTime(new Date());
                    amountDto.setCompanyId(String.valueOf(contract.getContractOrgId()));
                    ExchangeRateAmountDto s = accountingCenter.queryExchangeRateAmount(amountDto);
                    purchaseOrderDetail.setNoTaxAmount(DecimalUtils.toPlainString(s.getTransferAmount()));
                    purchaseOrderDetail.setCurrency(s.getCurrency());
                    return purchaseOrderDetail;
                })
                .filter(Objects::nonNull)
                .collect(Collectors.toList());
        if (CollectionUtils.isEmpty(detailList)) {
            return null;
        }
        purchaseOrderCreateApiDTO.setDetails(detailList);
        return purchaseOrderCreateApiDTO;
    }

