    /**
     * 重算PR完结状态
     *
     * @param prCode
     */
    private boolean recalculatePrCompletionStatus(String prCode) {
        if (StringUtils.isBlank(prCode)) {
            return false;
        }
        //3、PR自动完结：比较关联PR的预算金额 和 PR底下所有审核通过的PO的采购含税金额之和(含本单)
        //关联PR的预算金额
        PurchaseRequisitionDO requisition = purchaseRequisitionDAO.getByPrCode(prCode);
        BigDecimal totalBudgetUsd = commonService.getUsdAmountV2(requisition.getSettlementCurrency(), requisition.getTotalBudget());

        //该PR底下所有审核通过的PO的采购含税金额之和
        List<PurchaseOrderDO> purchaseOrderDOS = purchaseOrderDAO.getPassByPrCode(prCode);
        BigDecimal totalTaxInclusivePurchaseAmountUsd = getPoAllAmountUsd(purchaseOrderDOS);
        boolean isPrCompleted = DecimalUtils.getIntegerPart(totalTaxInclusivePurchaseAmountUsd) > DecimalUtils.getIntegerPart(totalBudgetUsd);
        PurchaseRequisitionDO newRequisition = new PurchaseRequisitionDO();
        newRequisition.setId(requisition.getId());
        newRequisition.setCompleteStatus(isPrCompleted ? CompleteStatusEnums.COMPLETED.getCode() : CompleteStatusEnums.INCOMPLETE.getCode());
        newRequisition.setCompleteDate(LocalDateTime.now());
        newRequisition.setCompleteUserCode("Auto");
        newRequisition.setCompleteUserName("Auto");
        newRequisition.setTwoDeptId(requisition.getTwoDeptId());
        BaseDOUtil.updateDO(newRequisition);
        purchaseRequisitionDAO.updateById(newRequisition);
        return isPrCompleted;
    }

    @Resource
    private WaukeenIntegration waukeenIntegration;

    /**
     * 生成预付款
     *
     * @param poCode
     * @param purchaseRequisitionDO
     * @param createSource
     */
    private void autoCreatePrepaidPy(String poCode,
                                     PurchaseRequisitionDO purchaseRequisitionDO,
                                     String createSource) {
        OrderBO orderBO = purchaseOrderManager.getOrderBO(poCode);
        PurchaseOrderDO purchaseOrderDO = orderBO.getPurchaseOrderDO();
        List<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOList = orderBO.getPurchaseOrderDetailBOList();
        List<PurchaseContractRedemptionPeriodDO> redemptionPeriodDOS = purchaseContractRedemptionPeriodDAO.getByContractCode(purchaseOrderDO.getContractCode());
        List<PurchaseContractRedemptionPeriodDO> downPaymentList = redemptionPeriodDOS.stream().filter(DO -> PaymentMethodEnums.DOWN_PAYMENT.getCode().equals(DO.getPaymentMethod())).collect(Collectors.toList());
        PurchasePaymentRequestDO purchasePaymentRequestDO = purchasePaymentRequestDAO.getByPoCodeAndPaymentType(purchaseOrderDO.getPoCode(), PaymentTypeEnums.PREPAID_AMOUNT.getCode());
        if (CollectionUtils.isNotEmpty(downPaymentList) && purchasePaymentRequestDO == null) {
            //新增PY表
            purchasePaymentRequestDO = new PurchasePaymentRequestDO();
            String pyCode = serialService.createPurchasePaymentRequestCode();
            purchasePaymentRequestDO.setPurchasePaymentRequestCode(pyCode);
            purchasePaymentRequestDO.setAuditStatus(SupplierDataStatusEnums.SAVE.getCode());
            purchasePaymentRequestDO.setPoCode(purchaseOrderDO.getPoCode());
            purchasePaymentRequestDO.setPrCode(purchaseOrderDO.getPrCode());
            purchasePaymentRequestDO.setContractCode(purchaseOrderDO.getContractCode());
            purchasePaymentRequestDO.setRequestDate(LocalDateTime.now());
            purchasePaymentRequestDO.setPaymentType(PaymentTypeEnums.PREPAID_AMOUNT.getCode());
            purchasePaymentRequestDO.setPayeeOrgType(PayeeOrgTypeEnums.SUPPLIER.getCode());
            purchasePaymentRequestDO.setSettledAmount(new BigDecimal("0"));
            PurchaseContractInfoDO purchaseContractInfoDO = purchaseContractInfoDAO.getByContractCode(purchasePaymentRequestDO.getContractCode());
            purchasePaymentRequestDO.setPaymentOrgId(purchaseContractInfoDO.getCostBearingOrgId());
            purchasePaymentRequestDO.setSupplierCode(purchaseContractInfoDO.getSupplierCode());
            purchasePaymentRequestDO.setApplicationOrgId(purchaseRequisitionDO.getApplicationOrgId());
            purchasePaymentRequestDO.setApplicantCode(purchaseRequisitionDO.getApplicantCode());
            purchasePaymentRequestDO.setCategorySubtypeCode(purchaseRequisitionDO.getCategorySubtypeCode());
            purchasePaymentRequestDO.setPurchaseOrgId(purchaseContractInfoDO.getContractOrgId());
            purchasePaymentRequestDO.setBuyerCode(purchaseOrderDO.getBuyerCode());
            BigDecimal downPaymentRatio = purchaseContractRedemptionPeriodDAO.getDownPaymentRatio(purchaseOrderDO.getContractCode());
            //申请付款金额——PO采购金额(含税)
            BigDecimal totalTaxInclusivePurchaseAmount = purchaseOrderDO.getTotalTaxInclusiveAmount();
            if (Objects.nonNull(totalTaxInclusivePurchaseAmount)) {
                purchasePaymentRequestDO.setRequiredPayment(totalTaxInclusivePurchaseAmount.multiply(downPaymentRatio).setScale(4, BigDecimal.ROUND_HALF_UP));
                purchasePaymentRequestDO.setAmountPayable(totalTaxInclusivePurchaseAmount.multiply(downPaymentRatio).setScale(4, BigDecimal.ROUND_HALF_UP));
                purchasePaymentRequestDO.setPurchaseAmount(totalTaxInclusivePurchaseAmount.setScale(4, BigDecimal.ROUND_HALF_UP));
            }
            purchasePaymentRequestDO.setOneDeptId(purchaseOrderDO.getOneDeptId());
            purchasePaymentRequestDO.setTwoDeptId(purchaseOrderDO.getTwoDeptId());
            purchasePaymentRequestDO.setPlatformAuditStatus(PaymentClassificationEnums.UNDER_CONFIRM.getCode());
            //落库汇率和申请付款金额（美元）
            if (purchasePaymentRequestDO.getRequiredPayment() != null && purchaseContractInfoDO != null && StringUtils.isNotBlank(purchaseContractInfoDO.getSettlementCurrency())) {
                BigDecimal expenseExchangeRate = waukeenIntegration.getExpenseExchangeRate(purchaseContractInfoDO.getSettlementCurrency(), DictConstant.USD);
                if (Objects.nonNull(expenseExchangeRate)) {
                    purchasePaymentRequestDO.setExchangeRate(expenseExchangeRate);
                    BigDecimal requiredPaymentUSD = purchasePaymentRequestDO.getRequiredPayment().multiply(expenseExchangeRate);
                    purchasePaymentRequestDO.setRequiredPaymentUSD(requiredPaymentUSD);
                }
            }
            //新增PY的Detail表（同PO采购编码）
            List<PurchasePaymentRequestDetailDO> purchasePaymentRequestDOS = new ArrayList<>();
            List<PurchaseOrderDetailDO> purchaseOrderDetailDOList = purchaseOrderDetailBOList.stream().map(OrderBO.PurchaseOrderDetailBO::getPurchaseOrderDetailDO).collect(Collectors.toList());
            for (PurchaseOrderDetailDO purchaseOrderDetailDO : purchaseOrderDetailDOList) {
                if (Objects.equals(purchaseOrderDetailDO.getPurchaseQty(), BigDecimal.ZERO)) {
                    continue;
                }
                PurchasePaymentRequestDetailDO purchasePaymentRequestDetailDO = new PurchasePaymentRequestDetailDO();
                purchasePaymentRequestDetailDO.setPurchasePaymentRequestCode(pyCode);
                purchasePaymentRequestDetailDO.setPurchaseItemCode(purchaseOrderDetailDO.getPurchaseItemCode());
                if(Objects.equals(CommonConstant.SYSTEM_AUTO_CREATE,createSource)) {
                    commonService.insertDO(purchasePaymentRequestDetailDO);
                } else {
                    BaseDOUtil.insertDO(purchasePaymentRequestDetailDO);
                }
                purchasePaymentRequestDOS.add(purchasePaymentRequestDetailDO);
            }
            purchasePaymentRequestDetailDAO.saveBatch(purchasePaymentRequestDOS);

            //新增PY费用分摊（同PO费用分摊）
            ArrayList<PurchasePaymentRequestBudgetAllocationDO> paymentRequestBudgetAllocationDOS = new ArrayList<>();
            List<PurchaseOrderBudgetAllocationDO> purchaseOrderBudgetAllocationDOS = purchaseOrderBudgetAllocationDAO.getByPoCode(purchaseOrderDO.getPoCode());
            for (PurchaseOrderBudgetAllocationDO purchaseOrderBudgetAllocationDO : purchaseOrderBudgetAllocationDOS) {
                PurchasePaymentRequestBudgetAllocationDO paymentRequestBudgetAllocationDO = new PurchasePaymentRequestBudgetAllocationDO();
                BeanUtils.copyProperties(purchaseOrderBudgetAllocationDO, paymentRequestBudgetAllocationDO);
                paymentRequestBudgetAllocationDO.setId(IdWorkerUtil.getId());
                paymentRequestBudgetAllocationDO.setPurchasePaymentRequestCode(pyCode);
                //计算费用分摊金额
                if(Objects.nonNull(purchaseOrderBudgetAllocationDO.getFeeBearingAmount()) && Objects.nonNull(downPaymentRatio)) {
                    paymentRequestBudgetAllocationDO.setFeeBearingAmount(purchaseOrderBudgetAllocationDO.getFeeBearingAmount()
                            .multiply(downPaymentRatio)
                            .setScale(DigitConstant.FOUR,RoundingMode.HALF_UP));
                } else if (purchasePaymentRequestDO.getRequiredPayment() != null && purchaseOrderBudgetAllocationDO.getFeeBearingPercentage() != null) {
                    paymentRequestBudgetAllocationDO.setFeeBearingAmount(purchasePaymentRequestDO.getRequiredPayment().multiply(purchaseOrderBudgetAllocationDO.getFeeBearingPercentage()));
                } else {
                    paymentRequestBudgetAllocationDO.setFeeBearingAmount(new BigDecimal("0"));
                }
                if(Objects.equals(CommonConstant.SYSTEM_AUTO_CREATE,createSource)) {
                    commonService.insertDO(paymentRequestBudgetAllocationDO);
                }
                paymentRequestBudgetAllocationDOS.add(paymentRequestBudgetAllocationDO);
            }

            purchasePaymentRequestManagerService.computeBudgetAllocation(purchasePaymentRequestDO,paymentRequestBudgetAllocationDOS);
            paymentRequestBudgetAllocationDAO.saveBatch(paymentRequestBudgetAllocationDOS);

            paymentManager.fillPySupplierAndSite(purchasePaymentRequestDO, purchaseContractInfoDO, purchaseOrderDO);
            //判断默认生成的费用分摊金额之和是否等于申请付款金额，若是，则展示在门户
            purchasePaymentRequestManagerService.checkIfShowInPlatform(purchasePaymentRequestDO, paymentRequestBudgetAllocationDOS);
            if(Objects.equals(CommonConstant.SYSTEM_AUTO_CREATE,createSource)) {
                commonService.insertDO(purchasePaymentRequestDO);
                EasyLogUtil.record(systemUserCode, purchasePaymentRequestDO.getPurchasePaymentRequestCode(), ModuleCode.PAYMENT, OperateType.CREATE, LogContentTemplate.PUSH_DOWN, new String[]{purchaseOrderDO.getPoCode()});
            } else {
                BaseDOUtil.insertDO(purchasePaymentRequestDO);
                EasyLogUtil.record(purchasePaymentRequestDO.getPurchasePaymentRequestCode(), ModuleCode.PAYMENT, OperateType.CREATE, LogContentTemplate.PUSH_DOWN, new String[]{purchaseOrderDO.getPoCode()});
            }
            purchasePaymentRequestDO.setSettlementMethod(SettlementMethodEnums.EFT.getCode());
            PaymentRequestBizOccurrenceVO requestBizOccurrenceVO = purchasePaymentRequestManagerService.getDefaultBizOccurrenceTimeV2(purchasePaymentRequestDO);
            purchasePaymentRequestDO.setBusinessOccurrenceTime(requestBizOccurrenceVO.getBizOccurrenceStartTime());
            purchasePaymentRequestDO.setBizOccurrenceEndTime(requestBizOccurrenceVO.getBizOccurrenceEndTime());
            purchasePaymentRequestDAO.save(purchasePaymentRequestDO);
        }
    }
