    /**
     * 发送邮件给供应商商务联系人和pr需求人,pr提交人邮箱
     *
     * @param purchaseOrderDO       po
     * @param purchaseRequisitionDO pr
     */
    private void sendEmail(PurchaseOrderDO purchaseOrderDO, PurchaseRequisitionDO purchaseRequisitionDO) {
        MailApiDTO mailApiDTO = new MailApiDTO();
        mailApiDTO.setTemplateCode(MailTemplateEnums.PO_MAIL.getCode());
        mailApiDTO.setSubject(MailTemplateEnums.PO_MAIL.getTitle());
        //发送人名称
        mailApiDTO.setSenderName("iMile Procurement");
        //供应商简称
        PurchaseContractInfoDO purchaseContractInfoDO = purchaseContractInfoDAO.getByContractCode(purchaseOrderDO.getContractCode());
        String supplierCode = purchaseContractInfoDO.getSupplierCode();
        SupplierBasicInfoDO supplierBasicInfoDO = supplierBasicInfoDAO.getLastBySupplierCode(supplierCode);
        HashMap<String, String> map = new HashMap<String, String>();
        map.put("field1", supplierBasicInfoDO.getSupplierShortNameEN());
        mailApiDTO.setFieldMap(map);

        List<String> emailList = new ArrayList<>();
        //1.供应商商务联系人邮箱（最新）
        if(Objects.equals(purchaseOrderDO.getIsNotifySupplier(),DigitConstant.ONE)) {
            List<SupplierContactInfoDO> supplierContactList = supplierContactInfoDAO.listBySupplierCodeAndVersionAndJob(supplierBasicInfoDO.getSupplierCode(), supplierBasicInfoDO.getRecordVersion(), JobTitleEnums.COMMERCIAL.getCode());
            String supplierContactEmail = supplierContactList.stream()
                    .filter(Objects::nonNull)
                    .map(SupplierContactInfoDO::getEmail)
                    .findFirst()
                    .orElse(StrUtil.EMPTY);
            emailList.add(supplierContactEmail);
        }
        //2.PR的需求人
        String applicantCode = purchaseRequisitionDO.getApplicantCode();
        if (StringUtils.isNotBlank(applicantCode)) {
            UserDTO user = hrmsIntegration.getUserByUserCode(applicantCode);
            if (StringUtils.isNotBlank(user.getEmail())) {
                emailList.add(user.getEmail());
            }
        }
        //2.PR的提交人
        List<PurchaseRequisitionAuditDO> prAuditList = purchaseRequisitionAuditDAO.getByPrCode(purchaseRequisitionDO.getPrCode());
        PurchaseRequisitionAuditDO lastPrAuditDO = prAuditList.stream()
                .filter(i -> Objects.equals(AuditStatusEnum.PASS.getCode(), i.getAuditStatus()))
                .max(Comparator.comparing(PurchaseRequisitionAuditDO::getCreateDate))
                .orElse(null);
        if (Objects.nonNull(lastPrAuditDO)){
            String prCreateUserCode = lastPrAuditDO.getCreateUserCode();
            if (StringUtils.isNotBlank(prCreateUserCode)){
                UserDTO user = hrmsIntegration.getUserByUserCode(prCreateUserCode);
                if (StringUtils.isNotBlank(user.getEmail())){
                    emailList.add(user.getEmail());
                }
            }
        }

        if (CollectionUtils.isNotEmpty(emailList)){
            String recipients = emailList.stream()
                    .filter(StringUtils::isNotBlank)
                    .distinct()
                    .collect(Collectors.joining(","));
            mailApiDTO.setRecipients(recipients);
            log.info("prCode={} pass send email recipients={}", purchaseRequisitionDO.getPrCode(), mailApiDTO.getRecipients());
            PrintParam printParam = new PrintParam();
            printParam.setCodeList(Lists.newArrayList(purchaseOrderDO.getPoCode()));
            List<PdfVO> voList = printService.getPoPdf("po_detail", printParam);
            List<FileTemplateDTO> fileTemplateDTOList = voList.stream()
                    .map(vo -> {
                        FileTemplateDTO fileTemplateDTO = new FileTemplateDTO();
                        fileTemplateDTO.setFileName(vo.getName());
                        fileTemplateDTO.setFileKey(vo.getFileKey());
                        fileTemplateDTO.setBucketType(1);
                        fileTemplateDTO.setFileUrl(vo.getFileUrl());
                        return fileTemplateDTO;
                    }).collect(Collectors.toList());
            mailApiDTO.setFileTemplates(fileTemplateDTOList);
            mailIntegration.sendMail(mailApiDTO);
        }
    }
