    /**
     * 审批驳回后的处理
     *
     * @param poCode
     * @param approvalRemark
     */
    @Override
    @Transactional
    public void reject(String poCode, String approvalRemark) {
        log.info("PO reject: " + poCode);
        String userCode = UcenterUtils.getUserInfo().getUserCode();
        UserDTO user = hrmsIntegration.getUserByUserCode(userCode);
        LocalDateTime now = LocalDateTime.now();
        //修改PO表的审核状态
        PurchaseOrderDO purchaseOrderDO = purchaseOrderDAO.getByPoCode(poCode);
        if (purchaseOrderDO == null) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getDesc()));
        }
        purchaseOrderDO.setAuditStatus(SupplierDataStatusEnums.REJECT.getCode());
        purchaseOrderDO.setAuditDate(now);
        purchaseOrderDO.setAuditUserCode(userCode);
        purchaseOrderDO.setAuditUserName(user.getUnifiedUserName());
        purchaseOrderDO.setApprovalInfoStatus(ApprovalInfoStatusEnums.REJECT.getCode());
        BaseDOUtil.updateDO(purchaseOrderDO);
        purchaseOrderDAO.updateById(purchaseOrderDO);

        //修改PO审核表最新审核记录
        PurchaseOrderAuditDO purchaseOrderAuditDO = purchaseOrderAuditDAO.getLastByPoCode(poCode);
        purchaseOrderAuditDO.setAuditStatus(SupplierDataStatusEnums.REJECT.getCode());
        purchaseOrderAuditDO.setAuditDate(now);
        purchaseOrderAuditDO.setAuditUserCode(userCode);
        purchaseOrderAuditDO.setAuditUserName(user.getUserName());
        purchaseOrderAuditDO.setAuditRejectReason(approvalRemark);
        BaseDOUtil.updateDO(purchaseOrderAuditDO);
        purchaseOrderAuditDAO.updateById(purchaseOrderAuditDO);
    }

    /**
     * 关联合同，补全PO信息
     *
     * @param prCode
     * @param contractCode
     * @param poCode
     * @return
     */
    @Override
    public String associateContract(String prCode, String contractCode, String poCode) {
        OrderBO orderBO = purchaseOrderManager.getOrderBO(poCode);

        PurchaseOrderDO purchaseOrderDO = orderBO.getPurchaseOrderDO();
        if (purchaseOrderDO == null) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_ORDER_NOT_EXIST.getDesc()));
        }
        //判断是否已关联
        if (StringUtils.isNotBlank(purchaseOrderDO.getContractCode())) {
            throw BusinessException.get(ErrorCodeEnums.HAVE_ASSOCIATED_CONTRACT.getCode(), I18nUtils.getMessage(ErrorCodeEnums.HAVE_ASSOCIATED_CONTRACT.getDesc()));
        }
        //判断合同是否存在、归档通过
        PurchaseContractInfoDO purchaseContractInfoDO = purchaseContractInfoDAO.getByContractCode(contractCode);
        if (purchaseContractInfoDO == null) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_CONTRACT_NOT_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_CONTRACT_NOT_EXIST.getDesc()));
        }
        if (!SupplierDataStatusEnums.PASS.getCode().equals(purchaseContractInfoDO.getFilingAuditStatus())) {
            throw BusinessException.get(ErrorCodeEnums.PURCHASE_CONTRACT_NOT_FILED.getCode(), I18nUtils.getMessage(ErrorCodeEnums.PURCHASE_CONTRACT_NOT_FILED.getDesc()));
        }
        //判断PR和合同的采购编码是否有交集
        List<PurchaseRequisitionDetailDO> prDetailDOS = prDetailDAO.getPrDetailByPrCode(prCode);
        List<String> itemCodesOfPr = prDetailDOS.stream().map(PurchaseRequisitionDetailDO::getPurchaseItemCode).collect(Collectors.toList());
        List<PurchaseContractDetailDO> contractDetailDOS = purchaseContractDetailDAO.getDetailByContractCode(contractCode);
        List<String> itemCodeResult = contractDetailDOS.stream()
                .map(PurchaseContractDetailDO::getPurchaseItemCode)
                .filter(itemCodesOfPr::contains)
                .distinct()
                .collect(Collectors.toList());
        if (CollectionUtils.isEmpty(itemCodeResult)) {
            throw BusinessException.get(ErrorCodeEnums.NO_IDENTICAL_PURCHASE_ITEM_CODE_EXIST.getCode(), I18nUtils.getMessage(ErrorCodeEnums.NO_IDENTICAL_PURCHASE_ITEM_CODE_EXIST.getDesc()));
        }
        //补全PO表
        purchaseOrderDO.setSiteNumber(purchaseContractInfoDO.getSiteNumber());
        purchaseOrderDO.setContractCode(contractCode);
        purchaseOrderDO.setShippingAddress(purchaseContractInfoDO.getShipFromAddress());

        ArrayList<OrderBO.PurchaseOrderDetailBO> purchaseOrderDetailBOList = new ArrayList<>();
        //新增 PO的detail表
        Map<String, PurchaseContractDetailDO> contractDetailDOMap = contractDetailDOS.stream()
                .collect(Collectors.toMap(PurchaseContractDetailDO::getPurchaseItemCode, Function.identity(), (k, v) -> k));
        Map<String, List<PurchaseContractDetailPriceSettingDO>> purchaseContractDetailPriceSettingDOMap = purchaseContractInfoManager.getItemDetailMap(purchaseOrderDO.getContractCode());
        for (String itemCode : itemCodeResult) {
            PurchaseOrderDetailDO purchaseOrderDetailDO = new PurchaseOrderDetailDO();
            purchaseOrderDetailDO.setPoCode(poCode);
            purchaseOrderDetailDO.setPurchaseItemCode(itemCode);
            PurchaseContractDetailDO purchaseContractDetailDO = contractDetailDOMap.get(itemCode);
            purchaseOrderDetailDO.setItemCodeTaxRate(purchaseContractDetailDO.getItemCodeTaxRate());
            purchaseOrderDetailDO.setPurchaseRemarks(purchaseContractDetailDO.getPurchaseRemarks());
            purchaseOrderDetailDO.setPriceMatchMode(purchaseContractDetailDO.getPriceMatchMode());
            purchaseOrderDetailDO.setChargingMethod(purchaseContractDetailDO.getChargingMethod());

            List<PurchaseContractDetailPriceSettingDO> subPurchaseContractDetailPriceSettingDOList = purchaseContractDetailPriceSettingDOMap.get(itemCode);
            List<OrderDetailPriceSettingDO> subOrderDetailPriceSettingDOList = new ArrayList<>();
            if (CollectionUtils.isNotEmpty(subPurchaseContractDetailPriceSettingDOList)) {
                subOrderDetailPriceSettingDOList = subPurchaseContractDetailPriceSettingDOList.stream()
                        .map(o -> {
                            OrderDetailPriceSettingDO orderDetailPriceSettingDO = new OrderDetailPriceSettingDO();
                            orderDetailPriceSettingDO.setPoCode(poCode);
                            orderDetailPriceSettingDO.setItemCode(o.getItemCode());
                            orderDetailPriceSettingDO.setPrice(o.getPrice());
                            orderDetailPriceSettingDO.setMinQty(o.getMinQty());
                            orderDetailPriceSettingDO.setMaxQty(o.getMaxQty());
                            return orderDetailPriceSettingDO;
                        }).collect(Collectors.toList());
            }
            OrderBO.PurchaseOrderDetailBO purchaseOrderDetailBO = new OrderBO.PurchaseOrderDetailBO();
            purchaseOrderDetailBO.setPurchaseOrderDetailDO(purchaseOrderDetailDO);
            purchaseOrderDetailBO.setOrderDetailPriceSettingDOList(subOrderDetailPriceSettingDOList);
            purchaseOrderDetailBOList.add(purchaseOrderDetailBO);
        }
        orderBO.setPurchaseOrderDO(purchaseOrderDO);
        orderBO.setPurchaseOrderDetailBOList(purchaseOrderDetailBOList);
        purchaseOrderManager.saveOrUpdate(orderBO);
        return purchaseOrderDO.getContractCode();
    }



    private List<String> itemCodeListBuildPoCodeList(PurchaseOrderPageQuery poPageQuery) {
        // 根据itemCodeList查询
        List<String> itemPoCodeList = null;
        if (CollectionUtils.isNotEmpty(poPageQuery.getItemCodeList())) {
            List<PurchaseOrderDetailDO> poDetailList = purchaseOrderDetailDAO.selectByItemCodeList(poPageQuery.getItemCodeList());
            itemPoCodeList = poDetailList.stream()
                    .filter(Objects::nonNull)
                    .map(PurchaseOrderDetailDO::getPoCode)
                    .collect(Collectors.toList());
        }
        if (CollectionUtils.isNotEmpty(poPageQuery.getPoCodeList()) && CollectionUtils.isNotEmpty(itemPoCodeList)) {
            List<String> poCodeList = poPageQuery.getPoCodeList();
            poCodeList.addAll(itemPoCodeList);
            poPageQuery.setPoCodeList(poCodeList);
        } else if (CollectionUtils.isEmpty(poPageQuery.getPoCodeList()) && CollectionUtils.isNotEmpty(itemPoCodeList)) {
            poPageQuery.setPoCodeList(itemPoCodeList);
        }
        return itemPoCodeList;
    }

